  created_at: string;
  courier_provider?: string | null;
  tracking_id?: string | null;
  delivery_failure_reason?: string | null;
  shipments?: Array<{
    id: string;
    status: string;
    warehouse_name?: string | null;
    courier_provider?: string | null;
    tracking_id?: string | null;
    delivery_failure_reason?: string | null;
  }>;
  items?: Array<{
    id: string;
    sku?: string | null;
    name?: string | null;
    variant_summary?: string | null;
  }>;
};

const shipmentStatuses = [
  'pending',
  'processing',
  'packed',
  'ready_for_pickup',
  'pickup_requested',
  'picked_up',
  'in_transit',
  'out_for_delivery',
  'delivered',
  'delivery_failed',
  'returned',
  'cancelled',
];

const activeStatuses = [
  'pending',
  'processing',
  'packed',
  'ready_for_pickup',
  'pickup_requested',
  'picked_up',
  'in_transit',
  'out_for_delivery',
];

const historyStatuses = ['delivered', 'delivery_failed', 'returned', 'cancelled'];

function getStatusTone(status: string) {
  switch (status) {
    case 'delivered':
      return 'bg-emerald-100 text-emerald-800';
    case 'out_for_delivery':
    case 'in_transit':
    case 'picked_up':
    case 'pickup_requested':
      return 'bg-indigo-100 text-indigo-800';
    case 'ready_for_pickup':
    case 'packed':
    case 'processing':
      return 'bg-amber-100 text-amber-800';
    case 'delivery_failed':
    case 'returned':
    case 'cancelled':
      return 'bg-rose-100 text-rose-800';
    default:
      return 'bg-slate-100 text-slate-700';
  }
}

export const AdminOrdersPage = () => {
  const { token } = useUser();
  const [orders, setOrders] = useState<AdminOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [view, setView] = useState<'all' | 'active' | 'exceptions' | 'history'>('all');
  const [error, setError] = useState('');
  const [updatingId, setUpdatingId] = useState('');
  const [focusedOrderId, setFocusedOrderId] = useState('');
  const [activeRenderCount, setActiveRenderCount] = useState(18);
  const [historyRenderCount, setHistoryRenderCount] = useState(16);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await fetch('/api/admin/orders', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load orders');
      }
      setOrders(Array.isArray(data) ? data : []);
    } catch (err) {
      setOrders([]);
      setError(err instanceof Error ? err.message : 'Failed to load orders');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) void fetchOrders();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    if (nextSearch) {
      setSearch(nextSearch);
    }
  }, []);

  const handleStatusChange = async (order: AdminOrder, status: string) => {
    try {
      setUpdatingId(order.id);

      const response = await fetch(`/api/admin/orders/${order.id}/status`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          status,
          courierProvider: order.courier_provider,
          trackingId: order.tracking_id,
          deliveryFailureReason:
            status === 'delivery_failed'
              ? order.delivery_failure_reason || 'Delivery exception requires manual follow-up'
              : null,
        }),
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to update status');
      }

      setOrders((current) =>
        current.map((item) =>
          item.id === order.id
            ? {
                ...item,
                status,
                delivery_failure_reason:
                  status === 'delivery_failed'
                    ? item.delivery_failure_reason || 'Delivery exception requires manual follow-up'
                    : status === 'returned'
                      ? item.delivery_failure_reason
                      : null,
              }
            : item,
        ),
      );
      toast.success(`Order moved to ${status.replaceAll('_', ' ')}`);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status');
    } finally {
      setUpdatingId('');
    }
  };

  const filteredOrders = useMemo(
    () =>
      orders.filter((order) => {
        const term = search.trim().toLowerCase();
        if (!term) return true;

        return (
          String(order.id).toLowerCase().includes(term) ||
          String(order.order_code || '').toLowerCase().includes(term) ||
          String(order.customer_name || '').toLowerCase().includes(term) ||
          String(order.customer_email || '').toLowerCase().includes(term) ||
          String(order.courier_provider || '').toLowerCase().includes(term) ||
          String(order.tracking_id || '').toLowerCase().includes(term) ||
          String(order.status || '').toLowerCase().includes(term) ||
          (Array.isArray(order.items)
            ? order.items
                .flatMap((item) => [item.name, item.sku, item.variant_summary])
                .filter(Boolean)
                .join(' ')
                .toLowerCase()
                .includes(term)
            : false)
        );
      }),
    [orders, search],
  );

  const viewScopedOrders = useMemo(() => {
    switch (view) {
      case 'active':
        return filteredOrders.filter((order) => activeStatuses.includes(order.status));
      case 'exceptions':
        return filteredOrders.filter((order) =>
          ['delivery_failed', 'returned', 'cancelled'].includes(order.status),
        );
      case 'history':
        return filteredOrders.filter((order) => historyStatuses.includes(order.status));
      default:
        return filteredOrders;
    }
  }, [filteredOrders, view]);

  const activeOrders = useMemo(
    () => viewScopedOrders.filter((order) => activeStatuses.includes(order.status)),
    [viewScopedOrders],
  );

  const courierHistory = useMemo(
    () => viewScopedOrders.filter((order) => historyStatuses.includes(order.status)),
    [viewScopedOrders],
  );

  const renderedActiveOrders = useMemo(
    () => activeOrders.slice(0, activeRenderCount),
    [activeOrders, activeRenderCount],
  );

  const renderedCourierHistory = useMemo(
    () => courierHistory.slice(0, historyRenderCount),
    [courierHistory, historyRenderCount],
  );

  useEffect(() => {
    setActiveRenderCount(18);
    setHistoryRenderCount(16);
  }, [search, view]);

  useEffect(() => {
    const needle = search.trim().toLowerCase();
    if (!needle) {
      setFocusedOrderId('');
      return;
    }

    const firstMatch = viewScopedOrders[0];
    if (!firstMatch) {
      setFocusedOrderId('');
      return;
    }

    setFocusedOrderId(firstMatch.id);

    if (typeof window !== 'undefined') {
      window.requestAnimationFrame(() => {
        document.getElementById(`admin-order-${firstMatch.id}`)?.scrollIntoView({
          behavior: 'smooth',
          block: 'center',
        });
      });
    }
  }, [search, viewScopedOrders]);

  const historySummary = useMemo(() => {
    const delivered = orders.filter((order) => order.status === 'delivered').length;
    const failed = orders.filter((order) => order.status === 'delivery_failed').length;
    const returned = orders.filter((order) => order.status === 'returned').length;

    return {
      total: orders.length,
      active: orders.filter((order) => activeStatuses.includes(order.status)).length,
      delivered,
      exceptionRate: orders.length > 0 ? Math.round(((failed + returned) / orders.length) * 100) : 0,
    };
  }, [orders]);

  const handleExport = () => {
    const headers = [
      'order_id',
      'customer',
      'email',
      'total',
      'status',
      'courier',
      'tracking',
      'shipment_count',
      'items',
      'created_at',
    ];
    const csv = [
      headers.join(','),
      ...viewScopedOrders.map((order) =>
        [
          order.order_code || order.id,
          order.customer_name || 'Customer',
          order.customer_email || '',
          order.total,
          order.status,
          order.courier_provider || '',
          order.tracking_id || '',
          Array.isArray(order.shipments) ? order.shipments.length : 0,
          Array.isArray(order.items)
            ? order.items
                .map((item) => (item.sku ? `${item.sku} ${item.name || ''}` : item.name || ''))
                .join(' | ')
            : '',
          order.created_at,
        ]
          .map((value) => `"${String(value ?? '').replaceAll('"', '""')}"`)
          .join(','),
      ),
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `admin-orders-${view}-${new Date().toISOString().slice(0, 10)}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  };

  if (loading) {
    return <TableSkeleton rows={6} columns={8} />;
  }

  return (
    <div className="space-y-6">
      {error ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          {error}
        </div>
      ) : null}

      <div className="mobile-sticky-toolbar flex flex-col gap-4 p-3 md:flex-row md:items-center md:justify-between md:p-0">
        <div>
          <h1 className="text-2xl font-bold">Order Management</h1>
          <p className="text-sm text-gray-500">
            Track courier progress, delivery exceptions, and customer impact.
          </p>
        </div>
        <div className="flex w-full flex-col gap-3 md:w-auto md:flex-row md:items-center">
          <div className="relative w-full md:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Search order, courier, tracking..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full rounded-xl border border-gray-200 bg-white py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/20 md:py-2"
            />
          </div>
          <button
            onClick={handleExport}
            className="inline-flex items-center justify-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-gray-50 md:py-2"
          >
            <Download size={16} />
            <span>Export CSV</span>
          </button>
        </div>
      </div>

      <div className="mobile-sticky-toolbar mt-3 flex flex-wrap gap-2 p-3 md:mt-0 md:p-0">
        {[
          { id: 'all', label: `All (${filteredOrders.length})` },
          {
            id: 'active',
            label: `Active (${filteredOrders.filter((order) => activeStatuses.includes(order.status)).length})`,
          },
          {
            id: 'exceptions',
            label: `Exceptions (${
              filteredOrders.filter((order) => ['delivery_failed', 'returned', 'cancelled'].includes(order.status))
                .length
            })`,
          },
          {
            id: 'history',
            label: `History (${filteredOrders.filter((order) => historyStatuses.includes(order.status)).length})`,
          },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setView(tab.id as typeof view)}
            className={`rounded-full px-4 py-2 text-xs font-bold uppercase tracking-wider transition ${
              view === tab.id
                ? 'bg-slate-900 text-white'
                : 'border border-slate-200 bg-white text-slate-600 hover:bg-slate-50'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Total Orders</p>
          <p className="mt-2 text-xl font-bold text-slate-900 md:text-2xl">{historySummary.total}</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Active Courier Queue</p>
          <p className="mt-2 text-xl font-bold text-indigo-700 md:text-2xl">{historySummary.active}</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Delivered</p>
          <p className="mt-2 text-xl font-bold text-emerald-700 md:text-2xl">{historySummary.delivered}</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Exception Rate</p>
          <p className="mt-2 text-xl font-bold text-amber-700 md:text-2xl">{historySummary.exceptionRate}%</p>
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
        <div className="border-b border-gray-100 px-4 py-4 md:px-6">
          <h3 className="font-bold text-slate-900">Active Courier Queue</h3>
          <p className="mt-1 text-sm text-gray-500">Monitor current pickup, transit, and delivery progress.</p>
        </div>

        <div className="space-y-3 p-4 md:hidden">
          {activeOrders.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-10 text-center text-sm text-gray-500">
              No active courier orders found.
            </div>
          ) : (
            renderedActiveOrders.map((order) => {
              const busy = updatingId === order.id;
              const focused = order.id === focusedOrderId;

              return (
                <div
                  id={`admin-order-${order.id}`}
                  key={order.id}
                  className={`space-y-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm ${
                    focused ? 'ring-2 ring-indigo-200' : ''
                  }`}
                >
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="text-sm font-bold text-slate-900">#{order.order_code || order.id}</p>
                      <p className="mt-1 text-xs text-gray-500">{new Date(order.created_at).toLocaleDateString()}</p>
                    </div>
                    <p className="text-sm font-bold text-primary">{formatPrice(order.total)}</p>
                  </div>

                  <div className="space-y-1">
                    <p className="text-sm font-semibold text-slate-900">{order.customer_name || 'Customer'}</p>
                    <p className="text-xs text-gray-500">{order.customer_email || 'No email'}</p>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    <span
                      className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-wider ${getStatusTone(
                        order.status,
                      )}`}
                    >
                      {order.status.replaceAll('_', ' ')}
                    </span>
                    <span className="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-700">
                      {order.courier_provider || 'Courier pending'}
                    </span>
                  </div>

                  <div className="space-y-2 rounded-2xl bg-slate-50 p-3">
                    <p className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">Tracking</p>
                    <p className="font-mono text-xs font-semibold text-slate-700">{order.tracking_id || 'Pending'}</p>
                    {Array.isArray(order.shipments) && order.shipments.length > 0 ? (
                      <div className="flex flex-wrap gap-1">
                        {order.shipments.slice(0, 3).map((shipment) => (
                          <span
                            key={shipment.id}
                            className="dashboard-stat-chip bg-white text-slate-600"
                          >
                            {shipment.warehouse_name || 'Pickup point'} /{' '}
                            {shipment.status.replaceAll('_', ' ')}
                          </span>
                        ))}
                      </div>
                    ) : null}
                    {Array.isArray(order.items) && order.items.length > 0 ? (
                      <div className="flex flex-wrap gap-1">
                        {order.items.slice(0, 2).map((item) => (
                          <span
                            key={item.id}
                            className="dashboard-stat-chip bg-white text-slate-600"
                          >
                            {item.sku || 'SKU pending'}
                          </span>
                        ))}
                      </div>
                    ) : null}
                  </div>

                  {order.delivery_failure_reason ? (
                    <div className="rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                      {order.delivery_failure_reason}
                    </div>
                  ) : null}

                  <div className="space-y-2">
                    <select
                      value={order.status}
                      onChange={(event) => void handleStatusChange(order, event.target.value)}
                      disabled={busy}
                      className={`w-full rounded-xl border-none px-3 py-2 text-xs font-bold uppercase tracking-wider focus:ring-2 focus:ring-primary/20 ${getStatusTone(
                        order.status,
                      )}`}
                    >
                      {shipmentStatuses.map((status) => (
                        <option key={status} value={status}>
                          {status.replaceAll('_', ' ')}
                        </option>
                      ))}
                    </select>
                    <div className="grid grid-cols-5 gap-2">
                      <button
                        onClick={() => void handleStatusChange(order, 'out_for_delivery')}
                        disabled={busy}
                        className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:text-indigo-600 disabled:opacity-50"
                      >
                        <Truck size={16} className="mx-auto" />
                      </button>
                      <button
                        onClick={() => void handleStatusChange(order, 'delivered')}
                        disabled={busy}
                        className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:text-emerald-600 disabled:opacity-50"
                      >
                        <CheckCircle size={16} className="mx-auto" />
                      </button>
                      <button
                        onClick={() => void handleStatusChange(order, 'delivery_failed')}
                        disabled={busy}
                        className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:text-amber-600 disabled:opacity-50"
                      >
                        <AlertTriangle size={16} className="mx-auto" />
                      </button>
                      <button
                        onClick={() => void handleStatusChange(order, 'returned')}
                        disabled={busy}
                        className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:text-rose-600 disabled:opacity-50"
                      >
                        <Undo2 size={16} className="mx-auto" />
                      </button>
                      <button
                        onClick={() => void handleStatusChange(order, 'cancelled')}
                        disabled={busy}
                        className="rounded-xl border border-slate-200 p-2 text-slate-500 hover:text-rose-700 disabled:opacity-50"
                      >
                        {busy ? (
                          <Loader2 size={16} className="mx-auto animate-spin" />
                        ) : (
                          <XCircle size={16} className="mx-auto" />
                        )}
                      </button>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {activeOrders.length > renderedActiveOrders.length ? (
          <div className="border-t border-slate-100 px-4 py-4 md:hidden">
            <button
              type="button"
              onClick={() => setActiveRenderCount((current) => current + 18)}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Load more active orders
            </button>
          </div>
        ) : null}

        <div className="hidden overflow-x-auto md:block">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
                <th className="px-6 py-4">Order</th>
                <th className="px-6 py-4">Customer</th>
                <th className="px-6 py-4">Total</th>
                <th className="px-6 py-4">Courier</th>
                <th className="px-6 py-4">Tracking</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4">Exception</th>
                <th className="px-6 py-4">Date</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {activeOrders.length === 0 ? (
                <tr>
                  <td colSpan={9} className="px-6 py-12 text-center text-gray-500">
                    No active courier orders found.
                  </td>
                </tr>
              ) : (
                renderedActiveOrders.map((order) => {
                  const busy = updatingId === order.id;
                  const focused = order.id === focusedOrderId;

                  return (
                    <tr
                      id={`admin-order-${order.id}`}
                      key={order.id}
                      className={`text-sm transition-colors hover:bg-gray-50 ${
                        focused ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200' : ''
                      }`}
                    >
                      <td className="px-6 py-4 font-medium">#{order.order_code || order.id}</td>
                      <td className="px-6 py-4">
                        <div>
                          <p className="font-bold">{order.customer_name || 'Customer'}</p>
                          <p className="text-xs text-gray-500">{order.customer_email || 'No email'}</p>
                        </div>
                      </td>
                      <td className="px-6 py-4 font-bold text-primary">{formatPrice(order.total)}</td>
                      <td className="px-6 py-4">
                        {order.courier_provider ? (
                          <span className="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-700">
                            {order.courier_provider}
                          </span>
                        ) : (
                          <span className="text-xs text-gray-400">Not assigned</span>
                        )}
                      </td>
                      <td className="px-6 py-4">
                        {order.tracking_id ? (
                          <span className="font-mono text-xs font-semibold text-slate-700">
                            {order.tracking_id}
                          </span>
                        ) : (
                          <span className="text-xs text-gray-400">Pending</span>
                        )}
                        {Array.isArray(order.shipments) && order.shipments.length > 0 ? (
                          <div className="mt-2 space-y-1">
                            <p className="text-[11px] text-slate-500">
                              {order.shipments.length} shipment{order.shipments.length > 1 ? 's' : ''}
                            </p>
                            <div className="flex flex-wrap gap-1">
                              {order.shipments.slice(0, 3).map((shipment) => (
                                <span
                                  key={shipment.id}
                                  className="dashboard-stat-chip bg-slate-100 text-slate-600"
                                >
                                  {shipment.warehouse_name || 'Pickup point'} /{' '}
                                  {shipment.status.replaceAll('_', ' ')}
                                </span>
                              ))}
                            </div>
                          </div>
                        ) : null}
                        {Array.isArray(order.items) && order.items.length > 0 ? (
                          <div className="mt-2 flex flex-wrap gap-1">
                            {order.items.slice(0, 2).map((item) => (
                              <span
                                key={item.id}
                                className="dashboard-stat-chip bg-white text-slate-600"
                              >
                                {item.sku || 'SKU pending'}
                              </span>
                            ))}
                          </div>
                        ) : null}
                      </td>
                      <td className="px-6 py-4">
                        <select
                          value={order.status}
                          onChange={(event) => void handleStatusChange(order, event.target.value)}
                          disabled={busy}
                          className={`rounded-full border-none px-2 py-1 text-[10px] font-bold uppercase tracking-wider focus:ring-2 focus:ring-primary/20 ${getStatusTone(
                            order.status,
                          )}`}
                        >
                          {shipmentStatuses.map((status) => (
                            <option key={status} value={status}>
                              {status.replaceAll('_', ' ')}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td className="px-6 py-4">
                        {order.delivery_failure_reason ? (
                          <div className="max-w-[180px] rounded-xl border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                            {order.delivery_failure_reason}
                          </div>
                        ) : (
                          <span className="text-xs text-gray-400">None</span>
                        )}
                      </td>
                      <td className="px-6 py-4 text-gray-500">
                        {new Date(order.created_at).toLocaleDateString()}
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex justify-end gap-2">
                          <button
                            onClick={() => void handleStatusChange(order, 'out_for_delivery')}
                            disabled={busy}
                            className="p-2 text-gray-400 transition-colors hover:text-indigo-600 disabled:opacity-50"
                            title="Mark out for delivery"
                          >
                            <Truck size={18} />
                          </button>
                          <button
                            onClick={() => void handleStatusChange(order, 'delivered')}
                            disabled={busy}
                            className="p-2 text-gray-400 transition-colors hover:text-emerald-600 disabled:opacity-50"
                            title="Mark delivered"
                          >
                            <CheckCircle size={18} />
                          </button>
                          <button
                            onClick={() => void handleStatusChange(order, 'delivery_failed')}
                            disabled={busy}
                            className="p-2 text-gray-400 transition-colors hover:text-amber-600 disabled:opacity-50"
                            title="Mark delivery failed"
                          >
                            <AlertTriangle size={18} />
                          </button>
                          <button
                            onClick={() => void handleStatusChange(order, 'returned')}
                            disabled={busy}
                            className="p-2 text-gray-400 transition-colors hover:text-rose-600 disabled:opacity-50"
                            title="Mark returned"
                          >
                            <Undo2 size={18} />
                          </button>
                          <button
                            onClick={() => void handleStatusChange(order, 'cancelled')}
                            disabled={busy}
                            className="p-2 text-gray-400 transition-colors hover:text-rose-700 disabled:opacity-50"
                            title="Cancel order"
                          >
                            {busy ? <Loader2 size={18} className="animate-spin" /> : <XCircle size={18} />}
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {activeOrders.length > renderedActiveOrders.length ? (
          <div className="hidden border-t border-slate-100 px-6 py-4 md:block">
            <button
              type="button"
              onClick={() => setActiveRenderCount((current) => current + 18)}
              className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Load more active orders
            </button>
          </div>
        ) : null}
      </div>

      <div className="overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
        <div className="flex items-center justify-between border-b border-gray-100 px-4 py-4 md:px-6">
          <div>
            <h3 className="font-bold text-slate-900">Courier History</h3>
            <p className="mt-1 text-sm text-gray-500">
              Review completed, failed, returned, and cancelled courier outcomes.
            </p>
          </div>
          <div className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600">
            {courierHistory.length} records
          </div>
        </div>

        <div className="space-y-3 p-4 md:hidden">
          {courierHistory.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-10 text-center text-sm text-gray-500">
              No courier history records found.
            </div>
          ) : (
            renderedCourierHistory.map((order) => (
              <div
                id={`admin-order-${order.id}`}
                key={order.id}
                className={`space-y-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm ${
                  order.id === focusedOrderId ? 'ring-2 ring-indigo-200' : ''
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p className="text-sm font-bold text-slate-900">#{order.order_code || order.id}</p>
                    <p className="mt-1 text-xs text-gray-500">{order.customer_name || 'Customer'}</p>
                  </div>
                  <span
                    className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-wider ${getStatusTone(
                      order.status,
                    )}`}
                  >
                    {order.status.replaceAll('_', ' ')}
                  </span>
                </div>
                <div className="rounded-2xl bg-slate-50 p-3 text-xs text-slate-600">
                  <p>{order.customer_email || 'No email'}</p>
                  <p className="mt-1 font-semibold">{order.courier_provider || 'Not assigned'}</p>
                  <p className="mt-1 font-mono">{order.tracking_id || 'Pending'}</p>
                  <p className="mt-2 text-[11px] text-slate-500">
                    {new Date(order.created_at).toLocaleDateString()}
                  </p>
                </div>
              </div>
            ))
          )}
        </div>

        {courierHistory.length > renderedCourierHistory.length ? (
          <div className="border-t border-slate-100 px-4 py-4 md:hidden">
            <button
              type="button"
              onClick={() => setHistoryRenderCount((current) => current + 16)}
              className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Load more history
            </button>
          </div>
        ) : null}

        <div className="hidden overflow-x-auto md:block">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
                <th className="px-6 py-4">Order</th>
                <th className="px-6 py-4">Customer</th>
                <th className="px-6 py-4">Courier</th>
                <th className="px-6 py-4">Tracking</th>
                <th className="px-6 py-4">Final Status</th>
                <th className="px-6 py-4">Date</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {courierHistory.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                    No courier history records found.
                  </td>
                </tr>
              ) : (
                renderedCourierHistory.map((order) => (
                  <tr
                    id={`admin-order-${order.id}`}
                    key={order.id}
                    className={`text-sm transition-colors hover:bg-gray-50 ${
                      order.id === focusedOrderId ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200' : ''
                    }`}
                  >
                    <td className="px-6 py-4 font-medium">#{order.order_code || order.id}</td>
                    <td className="px-6 py-4">
                      <p className="font-bold">{order.customer_name || 'Customer'}</p>
                      <p className="text-xs text-gray-500">{order.customer_email || 'No email'}</p>
                    </td>
                    <td className="px-6 py-4 text-xs font-semibold text-slate-700">
                      {order.courier_provider || 'Not assigned'}
                    </td>
                    <td className="px-6 py-4">
                      <span className="font-mono text-xs font-semibold text-slate-700">
                        {order.tracking_id || 'Pending'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span
                        className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-wider ${getStatusTone(
                          order.status,
                        )}`}
                      >
                        {order.status.replaceAll('_', ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-gray-500">
                      {new Date(order.created_at).toLocaleDateString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {courierHistory.length > renderedCourierHistory.length ? (
          <div className="hidden border-t border-slate-100 px-6 py-4 md:block">
            <button
              type="button"
              onClick={() => setHistoryRenderCount((current) => current + 16)}
              className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Load more history
            </button>
          </div>
        ) : null}
      </div>
    </div>
  );
};

'use client';

import React, { useEffect, useMemo, useState } from 'react';
import { Activity, Gauge, Loader2, RefreshCw, TimerReset, TriangleAlert } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';

type PerformanceMetricSummary = {
  name: string;
  average: number;
  samples: number;
  poor: number;
  needsImprovement: number;
};

type PerformanceRouteSummary = {
  route: string;
  samples: number;
  poor: number;
  avgLcp: number;
  avgInp: number;
};

type PerformanceSummaryResponse = {
  windowHours: number;
  totalEvents: number;
  lastUpdated: number | null;
  metrics: PerformanceMetricSummary[];
  routes: PerformanceRouteSummary[];
  timeline: Array<{
    label: string;
    samples: number;
    poor: number;
  }>;
  alerts: Array<{
    ts: number;
    route: string;
    metric: string;
    poorSamples: number;
    routePoorSamples: number;
    value?: number;
  }>;
  alert?: {
    severity: 'healthy' | 'warning' | 'critical';
    title: string;
    message: string;
  };
};

const emptySummary: PerformanceSummaryResponse = {
  windowHours: 24,
  totalEvents: 0,
  lastUpdated: null,
  metrics: [],
  routes: [],
  timeline: [],
  alerts: [],
};

const windowOptions = [
  { label: '1H', value: 1 },
  { label: '6H', value: 6 },
  { label: '24H', value: 24 },
  { label: '7D', value: 168 },
];

function getMetricUnit(name: string) {
  if (name === 'CLS') return '';
  return 'ms';
}

function getMetricStatus(metric: PerformanceMetricSummary) {
  if (metric.poor > 0) return { label: 'Needs attention', tone: 'text-rose-600 bg-rose-50 border-rose-200' };
  if (metric.needsImprovement > 0) return { label: 'Watch closely', tone: 'text-amber-700 bg-amber-50 border-amber-200' };
  return { label: 'Healthy', tone: 'text-emerald-700 bg-emerald-50 border-emerald-200' };
}

export const AdminPerformancePage = () => {
  const { token } = useUser();
  const [summary, setSummary] = useState<PerformanceSummaryResponse>(emptySummary);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [acknowledgingKey, setAcknowledgingKey] = useState('');
  const [acknowledgingAll, setAcknowledgingAll] = useState(false);
  const [error, setError] = useState('');
  const [windowHours, setWindowHours] = useState(24);

  const loadSummary = async (mode: 'initial' | 'refresh' = 'initial') => {
    if (!token) {
      setError('Please log in as an admin to view performance telemetry.');
      setLoading(false);
      return;
    }

    if (mode === 'initial') {
      setLoading(true);
    } else {
      setRefreshing(true);
    }

    try {
      setError('');
      const response = await fetch(`/api/admin/performance/web-vitals?hours=${windowHours}`, {
        headers: { Authorization: `Bearer ${token}` },
        cache: 'no-store',
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load performance telemetry');
      }

      setSummary({
        windowHours: Number(payload?.windowHours || windowHours),
        totalEvents: Number(payload?.totalEvents || 0),
        lastUpdated: payload?.lastUpdated ? Number(payload.lastUpdated) : null,
        metrics: Array.isArray(payload?.metrics) ? payload.metrics : [],
        routes: Array.isArray(payload?.routes) ? payload.routes : [],
        timeline: Array.isArray(payload?.timeline) ? payload.timeline : [],
        alerts: Array.isArray(payload?.alerts) ? payload.alerts : [],
        alert: payload?.alert,
      });
    } catch (requestError) {
      setSummary(emptySummary);
      setError(requestError instanceof Error ? requestError.message : 'Performance telemetry is unavailable right now.');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    void loadSummary('initial');
  }, [token, windowHours]);

  useEffect(() => {
    if (!token) return;

    const timer = window.setInterval(() => {
      void loadSummary('refresh');
    }, 60000);

    return () => window.clearInterval(timer);
  }, [token]);

  const metricCards = useMemo(
    () => summary.metrics.filter((metric) => ['LCP', 'CLS', 'INP', 'FCP', 'TTFB'].includes(metric.name)),
    [summary.metrics],
  );

  const routeCards = useMemo(() => summary.routes.slice(0, 12), [summary.routes]);

  const acknowledgeAlert = async (alert: PerformanceSummaryResponse['alerts'][number]) => {
    if (!token) return;

    const key = `${alert.ts}-${alert.route}-${alert.metric}`;
    setAcknowledgingKey(key);

    try {
      const response = await fetch('/api/admin/performance/web-vitals/acknowledge', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ts: alert.ts,
          route: alert.route,
          metric: alert.metric,
        }),
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to acknowledge alert');
      }

      setSummary((current) => ({
        ...current,
        alerts: current.alerts.filter((item) => !(item.ts === alert.ts && item.route === alert.route && item.metric === alert.metric)),
      }));
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to acknowledge alert');
    } finally {
      setAcknowledgingKey('');
    }
  };

  const acknowledgeAllVisibleAlerts = async () => {
    if (!token || summary.alerts.length === 0) return;

    setAcknowledgingAll(true);
    setError('');

    try {
      for (const alert of summary.alerts) {
        const response = await fetch('/api/admin/performance/web-vitals/acknowledge', {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            ts: alert.ts,
            route: alert.route,
            metric: alert.metric,
          }),
        });
        const payload = await response.json().catch(() => null);

        if (!response.ok) {
          throw new Error(payload?.error || 'Failed to acknowledge all alerts');
        }
      }

      setSummary((current) => ({
        ...current,
        alerts: [],
      }));
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to acknowledge all alerts');
    } finally {
      setAcknowledgingAll(false);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[320px] items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={28} />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Performance Telemetry</h1>
          <p className="text-gray-500">
            Real browser vitals from live users, grouped into practical route health summaries for operators.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex flex-wrap items-center gap-2 rounded-2xl border border-slate-200 bg-white p-1">
            {windowOptions.map((option) => (
              <button
                key={option.value}
                type="button"
                onClick={() => setWindowHours(option.value)}
                className={`rounded-xl px-3 py-1.5 text-xs font-semibold transition ${
                  windowHours === option.value
                    ? 'bg-slate-950 text-white'
                    : 'text-slate-600 hover:bg-slate-100'
                }`}
              >
                {option.label}
              </button>
            ))}
          </div>
          <div className="rounded-full bg-slate-100 px-4 py-2 text-sm font-semibold text-slate-700">
            {summary.totalEvents} live samples
          </div>
          <button
            type="button"
            onClick={() => void loadSummary('refresh')}
            disabled={refreshing}
            className="inline-flex items-center gap-2 rounded-2xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-700 transition hover:border-primary hover:text-primary disabled:opacity-60"
          >
            <RefreshCw size={16} className={refreshing ? 'animate-spin' : ''} />
            {refreshing ? 'Refreshing...' : 'Refresh'}
          </button>
        </div>
      </div>

      {error ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">{error}</div>
      ) : null}

      {summary.alert ? (
        <div
          className={`rounded-2xl border p-5 ${
            summary.alert.severity === 'critical'
              ? 'border-rose-200 bg-rose-50 text-rose-800'
              : summary.alert.severity === 'warning'
                ? 'border-amber-200 bg-amber-50 text-amber-800'
                : 'border-emerald-200 bg-emerald-50 text-emerald-800'
          }`}
        >
          <p className="font-semibold">{summary.alert.title}</p>
          <p className="mt-1 text-sm">{summary.alert.message}</p>
        </div>
      ) : null}

      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-5">
        {metricCards.length === 0 ? (
          <div className="rounded-3xl border border-dashed border-slate-300 bg-white p-6 text-sm text-slate-500 xl:col-span-5">
            Waiting for live browser vitals to arrive from real traffic.
          </div>
        ) : (
          metricCards.map((metric) => {
            const status = getMetricStatus(metric);
            return (
              <div key={metric.name} className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm">
                <div className="mb-4 flex items-start justify-between gap-3">
                  <div className="rounded-2xl bg-slate-100 p-3 text-slate-700">
                    <Gauge className="h-5 w-5" />
                  </div>
                  <span className={`rounded-full border px-3 py-1 text-[11px] font-semibold uppercase tracking-wide ${status.tone}`}>
                    {status.label}
                  </span>
                </div>
                <p className="text-sm text-slate-500">{metric.name}</p>
                <p className="mt-1 text-3xl font-bold text-slate-950">
                  {metric.average}
                  <span className="ml-1 text-base font-semibold text-slate-400">{getMetricUnit(metric.name)}</span>
                </p>
                <div className="mt-4 flex flex-wrap gap-3 text-xs text-slate-500">
                  <span>{metric.samples} samples</span>
                  <span>{metric.poor} poor</span>
                  <span>{metric.needsImprovement} watch</span>
                </div>
              </div>
            );
          })
        )}
      </div>

      <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm">
        <div className="flex items-center justify-between gap-4">
          <div>
            <h2 className="text-lg font-bold">Recent telemetry timeline</h2>
            <p className="text-sm text-slate-500">
              Rolling sample flow across the last {summary.windowHours} hour{summary.windowHours > 1 ? 's' : ''}.
            </p>
          </div>
        </div>
        <div className="mt-6 grid grid-cols-2 gap-4 md:grid-cols-3 xl:grid-cols-6">
          {summary.timeline.length === 0 ? (
            <p className="text-sm text-slate-500 xl:col-span-6">Timeline buckets will appear after real visits.</p>
          ) : (
            summary.timeline.map((bucket) => {
              const barHeight = Math.max(12, Math.min(100, bucket.samples * 8));
              return (
                <div key={bucket.label} className="rounded-2xl border border-slate-100 bg-slate-50 p-4">
                  <div className="flex items-end gap-2">
                    <div className="flex h-24 items-end">
                      <div
                        className="w-8 rounded-t-xl bg-slate-900/85"
                        style={{ height: `${barHeight}%` }}
                      />
                    </div>
                    <div className="text-xs text-slate-500">
                      <p className="font-semibold text-slate-900">{bucket.samples}</p>
                      <p>{bucket.poor} poor</p>
                    </div>
                  </div>
                  <p className="mt-3 text-xs font-semibold uppercase tracking-wide text-slate-500">{bucket.label}</p>
                </div>
              );
            })
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 gap-8 xl:grid-cols-[1.1fr_0.9fr]">
        <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm">
          <div className="flex items-center justify-between gap-4">
            <div>
              <h2 className="text-lg font-bold">Slow route watchlist</h2>
              <p className="text-sm text-slate-500">
                Highest-friction routes ordered by poor samples and slower contentful paint.
              </p>
            </div>
            <div className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600">
              Top {routeCards.length}
            </div>
          </div>

          <div className="mt-6 space-y-4">
            {routeCards.length === 0 ? (
              <p className="text-sm text-slate-500">Route-level telemetry will appear after real visits.</p>
            ) : (
              routeCards.map((route) => (
                <div key={route.route} className="rounded-2xl border border-slate-100 bg-slate-50 p-4">
                  <div className="flex items-center justify-between gap-4">
                    <p className="truncate font-semibold text-slate-950">{route.route}</p>
                    <span className="rounded-full bg-rose-50 px-3 py-1 text-xs font-semibold text-rose-600">
                      {route.poor} poor
                    </span>
                  </div>
                  <div className="mt-3 grid grid-cols-1 gap-3 text-xs text-slate-600 sm:grid-cols-3">
                    <div className="rounded-xl bg-white px-3 py-2">Samples: {route.samples}</div>
                    <div className="rounded-xl bg-white px-3 py-2">Avg LCP: {route.avgLcp}ms</div>
                    <div className="rounded-xl bg-white px-3 py-2">Avg INP: {route.avgInp}ms</div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-6">
          <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm">
            <div className="flex items-start justify-between gap-4">
              <div>
                <h2 className="flex items-center gap-2 text-lg font-bold text-slate-950">
                  <TriangleAlert className="h-5 w-5 text-amber-600" />
                  Recent triggered alerts
                </h2>
                <p className="mt-1 text-sm text-slate-500">
                  Cooldown-aware incidents raised from real poor vitals bursts.
                </p>
              </div>
              {summary.alerts.length > 1 ? (
                <button
                  type="button"
                  onClick={() => void acknowledgeAllVisibleAlerts()}
                  disabled={acknowledgingAll}
                  className="rounded-full border border-slate-200 bg-white px-4 py-2 text-xs font-semibold text-slate-700 transition hover:border-primary hover:text-primary disabled:opacity-60"
                >
                  {acknowledgingAll ? 'Saving...' : 'Acknowledge all visible'}
                </button>
              ) : null}
            </div>

            <div className="mt-5 space-y-3">
              {summary.alerts.length === 0 ? (
                <p className="text-sm text-slate-500">No triggered incidents in this window.</p>
              ) : (
                summary.alerts.map((item) => (
                  <div key={`${item.ts}-${item.route}-${item.metric}`} className="rounded-2xl border border-amber-100 bg-amber-50 p-4">
                    <div className="flex items-start justify-between gap-4">
                      <div>
                        <p className="font-semibold text-slate-950">{item.metric} alert on {item.route}</p>
                        <p className="mt-1 text-xs text-slate-600">
                          {item.poorSamples} poor samples in the last 10 minutes, including {item.routePoorSamples} on this route.
                        </p>
                      </div>
                      <div className="flex flex-col items-end gap-2">
                        <span className="whitespace-nowrap text-xs font-semibold text-amber-700">
                          {new Date(item.ts).toLocaleString()}
                        </span>
                        <button
                          type="button"
                          onClick={() => void acknowledgeAlert(item)}
                          disabled={acknowledgingKey === `${item.ts}-${item.route}-${item.metric}`}
                          className="rounded-full bg-white px-3 py-1 text-xs font-semibold text-slate-700 transition hover:text-primary disabled:opacity-60"
                        >
                          {acknowledgingKey === `${item.ts}-${item.route}-${item.metric}` ? 'Saving...' : 'Acknowledge'}
                        </button>
                      </div>
                    </div>
                    <div className="mt-3 flex flex-wrap gap-3 text-xs text-slate-600">
                      <span className="rounded-full bg-white px-3 py-1">Route poor: {item.routePoorSamples}</span>
                      <span className="rounded-full bg-white px-3 py-1">Window poor: {item.poorSamples}</span>
                      {typeof item.value === 'number' ? (
                        <span className="rounded-full bg-white px-3 py-1">Latest value: {Math.round(item.value)}</span>
                      ) : null}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm">
            <h2 className="flex items-center gap-2 text-lg font-bold text-slate-950">
              <Activity className="h-5 w-5 text-primary" />
              Operator notes
            </h2>
            <div className="mt-5 space-y-4 text-sm text-slate-600">
              <div className="rounded-2xl bg-slate-50 p-4">
                <p className="font-semibold text-slate-900">Focus on LCP first</p>
                <p className="mt-1 leading-6">
                  When slow route samples cluster, improving above-the-fold rendering usually gives the fastest user-facing win.
                </p>
              </div>
              <div className="rounded-2xl bg-slate-50 p-4">
                <p className="font-semibold text-slate-900">Watch INP for interaction-heavy pages</p>
                <p className="mt-1 leading-6">
                  Product, community, and dashboard routes benefit most from lower interaction delay after bundle trimming.
                </p>
              </div>
              <div className="rounded-2xl bg-slate-50 p-4">
                <p className="font-semibold text-slate-900">Keep collecting live traffic</p>
                <p className="mt-1 leading-6">
                  This view improves as more real sessions land. Low sample counts are useful, but trends become stronger with production traffic.
                </p>
              </div>
            </div>
          </div>

          <div className="rounded-3xl border border-slate-100 bg-white p-6 shadow-sm">
            <h2 className="flex items-center gap-2 text-lg font-bold text-slate-950">
              <TimerReset className="h-5 w-5 text-primary" />
              Last collection window
            </h2>
            <div className="mt-5 rounded-2xl bg-slate-50 p-4 text-sm text-slate-600">
              {summary.lastUpdated ? (
                <p>
                  Latest browser sample received at{' '}
                  <span className="font-semibold text-slate-900">{new Date(summary.lastUpdated).toLocaleString()}</span>.
                </p>
              ) : (
                <p>No live performance sample has been received yet.</p>
              )}
            </div>
            <div className="mt-4 flex items-start gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
              <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0" />
              <p>
                Telemetry is lightweight and rolling. The latest summaries keep recent browser events instead of storing unlimited history.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPerformancePage;

import React, { useEffect, useMemo, useState } from 'react';
import { CheckCircle2, Loader2, Search, ShieldAlert, Undo2, XCircle } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';
import toast from '@/lib/toast';

type ReturnRequestRecord = {
  id: string;
  order_id: string | null;
  type: string;
  status: string;
  reason: string | null;
  resolution_note: string | null;
  processed_at: string | null;
  created_at: string;
  customer: {
    id: string;
    name: string | null;
    email: string | null;
  } | null;
  order: {
    id: string;
    total: number;
    status: string;
    payment_status: string | null;
    courier_provider: string | null;
    tracking_id: string | null;
    created_at: string | null;
  } | null;
  processed_by: {
    id: string;
    name: string | null;
    email: string | null;
  } | null;
};

type ReturnSummary = {
  total: number;
  pending: number;
  approved: number;
  rejected: number;
  refunded: number;
};

function getStatusTone(status: string) {
  switch (String(status).toLowerCase()) {
    case 'pending':
      return 'bg-amber-100 text-amber-800';
    case 'approved':
      return 'bg-blue-100 text-blue-800';
    case 'refunded':
      return 'bg-emerald-100 text-emerald-800';
    case 'rejected':
      return 'bg-rose-100 text-rose-800';
    default:
      return 'bg-slate-100 text-slate-700';
  }
}

export const AdminReturnsPage = () => {
  const { token } = useUser();
  const [requests, setRequests] = useState<ReturnRequestRecord[]>([]);
  const [summary, setSummary] = useState<ReturnSummary>({ total: 0, pending: 0, approved: 0, rejected: 0, refunded: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<'all' | 'pending' | 'approved' | 'rejected' | 'refunded'>('all');
  const [updatingId, setUpdatingId] = useState('');
  const [resolutionNotes, setResolutionNotes] = useState<Record<string, string>>({});
  const [focusedRequestId, setFocusedRequestId] = useState('');

  const loadReturns = async () => {
    if (!token) {
      setError('Please log in as an admin to review returns.');
      setRequests([]);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError('');
      const response = await fetch('/api/admin/return-requests', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load return requests');
      }
      setRequests(Array.isArray(payload?.requests) ? payload.requests : []);
      setSummary(payload?.summary || { total: 0, pending: 0, approved: 0, rejected: 0, refunded: 0 });
    } catch (err) {
      setRequests([]);
      setSummary({ total: 0, pending: 0, approved: 0, rejected: 0, refunded: 0 });
      setError(err instanceof Error ? err.message : 'Failed to load return requests');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadReturns();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    const nextRequest = params.get('request');

    if (nextSearch) {
      setSearch(nextSearch);
    }
    if (nextRequest) {
      setFocusedRequestId(nextRequest);
    }
  }, []);

  const filteredRequests = useMemo(() => {
    const term = search.trim().toLowerCase();

    return requests.filter((request) => {
      const matchesFilter = filter === 'all' ? true : request.status === filter;
      if (!matchesFilter) return false;
      if (!term) return true;

      return [
        request.id,
        request.order?.id || '',
        request.customer?.name || '',
        request.customer?.email || '',
        request.order?.tracking_id || '',
        request.order?.courier_provider || '',
        request.reason || '',
        request.status || '',
      ]
        .join(' ')
        .toLowerCase()
        .includes(term);
    });
  }, [filter, requests, search]);

  useEffect(() => {
    if (!focusedRequestId || filteredRequests.length === 0 || typeof window === 'undefined') return;

    const matched = filteredRequests.find((request) => request.id === focusedRequestId);
    if (!matched) return;

    window.requestAnimationFrame(() => {
      document.getElementById(`admin-return-request-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [filteredRequests, focusedRequestId]);

  const handleAction = async (request: ReturnRequestRecord, status: 'approved' | 'rejected' | 'refunded') => {
    const resolutionNote = (resolutionNotes[request.id] || '').trim();

    if (status === 'rejected' && resolutionNote.length < 5) {
      toast.error('Add a short rejection note before rejecting the request.');
      return;
    }

    try {
      setUpdatingId(request.id);
      const response = await fetch(`/api/admin/return-requests/${request.id}/review`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status, resolutionNote }),
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to update return request');
      }

      setRequests((current) =>
        current.map((item) =>
          item.id === request.id
            ? {
                ...item,
                status,
                resolution_note: resolutionNote || item.resolution_note,
                processed_at: payload?.request?.processed_at || new Date().toISOString(),
              }
            : item,
        ),
      );

      setSummary((current) => {
        const next = { ...current };
        const previousStatus = String(request.status || 'pending').toLowerCase() as keyof ReturnSummary;
        const nextStatus = status as keyof ReturnSummary;

        if (previousStatus in next) {
          next[previousStatus] = Math.max(0, Number(next[previousStatus]) - 1);
        }
        if (nextStatus in next) {
          next[nextStatus] = Number(next[nextStatus]) + 1;
        }
        return next;
      });

      toast.success(
        status === 'approved'
          ? 'Return request approved'
          : status === 'rejected'
            ? 'Return request rejected'
            : 'Return marked as refunded',
      );
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update return request');
    } finally {
      setUpdatingId('');
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {error ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          {error}
        </div>
      ) : null}

      <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="text-2xl font-bold">Returns Queue</h1>
          <p className="text-sm text-gray-500">Review customer return requests, approve resolutions, and confirm refund completion.</p>
        </div>
        <div className="flex flex-col gap-3 sm:flex-row">
          <div className="relative w-full sm:w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Search order, tracking, customer..."
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              className="w-full rounded-xl border border-gray-200 bg-white py-2 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/20"
            />
          </div>
          <select
            value={filter}
            onChange={(event) => setFilter(event.target.value as typeof filter)}
            className="rounded-xl border border-gray-200 bg-white px-4 py-2 text-sm focus:ring-2 focus:ring-primary/20"
          >
            <option value="all">All statuses</option>
            <option value="pending">Pending</option>
            <option value="approved">Approved</option>
            <option value="refunded">Refunded</option>
            <option value="rejected">Rejected</option>
          </select>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-5">
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Total</p>
          <p className="mt-2 text-xl font-bold text-gray-900 md:text-2xl">{summary.total}</p>
        </div>
        <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4 md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-amber-700">Pending</p>
          <p className="mt-2 text-xl font-bold text-amber-900 md:text-2xl">{summary.pending}</p>
        </div>
        <div className="rounded-2xl border border-blue-200 bg-blue-50 p-4 md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-blue-700">Approved</p>
          <p className="mt-2 text-xl font-bold text-blue-900 md:text-2xl">{summary.approved}</p>
        </div>
        <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4 md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-emerald-700">Refunded</p>
          <p className="mt-2 text-xl font-bold text-emerald-900 md:text-2xl">{summary.refunded}</p>
        </div>
        <div className="rounded-2xl border border-rose-200 bg-rose-50 p-4 md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-rose-700">Rejected</p>
          <p className="mt-2 text-xl font-bold text-rose-900 md:text-2xl">{summary.rejected}</p>
        </div>
      </div>

      {filteredRequests.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-gray-200 bg-white px-6 py-14 text-center text-sm text-gray-500">
          No return requests match the current filter.
        </div>
      ) : (
        <div className="space-y-4">
          {filteredRequests.map((request) => {
            const isUpdating = updatingId === request.id;
            const currentNote = resolutionNotes[request.id] ?? request.resolution_note ?? '';

            return (
              <div
                id={`admin-return-request-${request.id}`}
                key={request.id}
                className={`rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-6 ${
                  request.id === focusedRequestId ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30' : ''
                }`}
              >
                <div className="flex flex-col gap-4 xl:flex-row xl:items-start xl:justify-between">
                  <div className="space-y-3">
                    <div className="flex flex-wrap items-center gap-3">
                      <h2 className="text-lg font-bold text-gray-900">Return #{request.id.slice(-8).toUpperCase()}</h2>
                      <span className={`rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-wider ${getStatusTone(request.status)}`}>
                        {String(request.status).replaceAll('_', ' ')}
                      </span>
                    </div>
                    <div className="grid gap-2 text-sm text-gray-600 md:grid-cols-2">
                      <p><span className="font-semibold text-gray-900">Customer:</span> {request.customer?.name || 'Customer'} {request.customer?.email ? `(${request.customer.email})` : ''}</p>
                      <p><span className="font-semibold text-gray-900">Order:</span> {request.order?.id || request.order_id || 'Not linked'}</p>
                      <p><span className="font-semibold text-gray-900">Order total:</span> {request.order ? formatPrice(Number(request.order.total || 0)) : 'N/A'}</p>
                      <p><span className="font-semibold text-gray-900">Payment:</span> {request.order?.payment_status || 'untracked'}</p>
                      <p><span className="font-semibold text-gray-900">Courier:</span> {request.order?.courier_provider || 'Not assigned yet'}</p>
                      <p><span className="font-semibold text-gray-900">Tracking:</span> {request.order?.tracking_id || 'Not available'}</p>
                    </div>
                    <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-700">
                      <p className="font-semibold text-slate-900">Customer reason</p>
                      <p className="mt-2 whitespace-pre-wrap">{request.reason || 'No reason provided.'}</p>
                    </div>
                    {request.processed_at ? (
                      <div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-4 text-sm text-emerald-800">
                        <p className="font-semibold">Last resolution update</p>
                        <p className="mt-1">
                          {request.processed_by?.name || 'Admin'} updated this request on {new Date(request.processed_at).toLocaleString()}.
                        </p>
                        {request.resolution_note ? <p className="mt-2">{request.resolution_note}</p> : null}
                      </div>
                    ) : null}
                  </div>

                  <div className="w-full max-w-xl space-y-4 rounded-2xl border border-slate-200 bg-slate-50 p-4">
                    <div className="flex items-center gap-2 text-sm font-semibold text-slate-900">
                      <ShieldAlert size={18} className="text-primary" />
                      <span>Resolution workspace</span>
                    </div>
                    <textarea
                      rows={4}
                      value={currentNote}
                      onChange={(event) =>
                        setResolutionNotes((current) => ({
                          ...current,
                          [request.id]: event.target.value,
                        }))
                      }
                      placeholder="Add a review note, refund note, or rejection explanation"
                      className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm outline-none transition focus:border-primary/30 focus:ring-4 focus:ring-primary/10"
                    />
                    <div className="grid gap-3 sm:grid-cols-3">
                      <button
                        onClick={() => void handleAction(request, 'approved')}
                        disabled={isUpdating || request.status !== 'pending'}
                        className="inline-flex items-center justify-center gap-2 rounded-2xl border border-blue-200 bg-blue-50 px-4 py-3 text-sm font-semibold text-blue-800 transition hover:bg-blue-100 disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {isUpdating ? <Loader2 size={16} className="animate-spin" /> : <CheckCircle2 size={16} />}
                        <span>Approve</span>
                      </button>
                      <button
                        onClick={() => void handleAction(request, 'rejected')}
                        disabled={isUpdating || !['pending', 'approved'].includes(request.status)}
                        className="inline-flex items-center justify-center gap-2 rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-800 transition hover:bg-rose-100 disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {isUpdating ? <Loader2 size={16} className="animate-spin" /> : <XCircle size={16} />}
                        <span>Reject</span>
                      </button>
                      <button
                        onClick={() => void handleAction(request, 'refunded')}
                        disabled={isUpdating || request.status !== 'approved'}
                        className="inline-flex items-center justify-center gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800 transition hover:bg-emerald-100 disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {isUpdating ? <Loader2 size={16} className="animate-spin" /> : <Undo2 size={16} />}
                        <span>Mark refunded</span>
                      </button>
                    </div>
                    <div className="rounded-2xl border border-slate-200 bg-white px-4 py-3 text-xs text-slate-500">
                      Approve when the request is valid, reject with a clear note when policy does not allow the return, and mark refunded only after the money flow is actually completed.
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Search, Star, Trash2, Loader2, MessageSquare } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import toast from '@/lib/toast';

export const AdminReviewsPage = () => {
  const { token } = useUser();
  const [reviews, setReviews] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);

  const fetchReviews = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await fetch('/api/admin/reviews', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load reviews');
      }
      setReviews(data);
    } catch (err) {
      setReviews([]);
      setError(err instanceof Error ? err.message : 'Failed to load reviews');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) fetchReviews();
  }, [token]);

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/admin/reviews/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to delete review');
      }
      setDeleteConfirmId(null);
      toast.success('Review deleted');
      fetchReviews();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete review');
    }
  };

  const filteredReviews = reviews.filter(r => 
    (r.comment || '').toLowerCase().includes(search.toLowerCase()) ||
    (r.user_name || '').toLowerCase().includes(search.toLowerCase()) ||
    (r.product_name || '').toLowerCase().includes(search.toLowerCase())
  );

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <Loader2 className="animate-spin text-primary" size={32} />
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">Review Moderation</h1>
          <p className="text-sm text-gray-500">Monitor and manage product reviews</p>
        </div>
        <div className="relative w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search reviews..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-white border border-gray-200 rounded-xl py-2 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/20" 
          />
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {error && (
          <div className="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
            {error}
          </div>
        )}
        {filteredReviews.map((review) => (
          <div key={review.id} className="bg-white p-6 rounded-2xl border border-black/5 shadow-sm flex items-start space-x-4 group">
            <div className="p-3 bg-gray-50 rounded-xl text-gray-400">
              <MessageSquare size={24} />
            </div>
            <div className="flex-1">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-bold">{review.user_name}</h3>
                  <p className="text-xs text-gray-500 mb-2">on <span className="text-primary font-medium">{review.product_name}</span></p>
                  <div className="flex items-center space-x-1 mb-3">
                    {[...Array(5)].map((_, i) => (
                      <Star 
                        key={i} 
                        size={14} 
                        className={i < review.rating ? "fill-yellow-400 text-yellow-400" : "text-gray-200"} 
                      />
                    ))}
                  </div>
                </div>
                {deleteConfirmId === review.id ? (
                  <div className="flex items-center gap-2 rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700">
                    <span>Delete?</span>
                    <button
                      onClick={() => handleDelete(review.id)}
                      className="rounded-lg bg-rose-600 px-2.5 py-1 text-white transition hover:bg-rose-700"
                    >
                      Confirm
                    </button>
                    <button
                      onClick={() => setDeleteConfirmId(null)}
                      className="rounded-lg border border-slate-200 bg-white px-2.5 py-1 text-slate-600 transition hover:bg-slate-50"
                    >
                      Cancel
                    </button>
                  </div>
                ) : (
                  <button 
                    onClick={() => setDeleteConfirmId(review.id)}
                    className="p-2 text-gray-400 hover:text-accent opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Trash2 size={18} />
                  </button>
                )}
              </div>
              <p className="text-sm text-gray-600 leading-relaxed italic">"{review.comment}"</p>
              <p className="text-[10px] text-gray-400 mt-4 uppercase tracking-wider">
                {new Date(review.created_at).toLocaleString()}
              </p>
            </div>
          </div>
        ))}
        {filteredReviews.length === 0 && (
          <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-200">
            <p className="text-gray-500">No reviews found.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { CheckCircle, ExternalLink, Eye, Loader2, Search, ShieldAlert, Store } from 'lucide-react';
import toast from '@/lib/toast';
import { useNavigate } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';

type SellerRow = {
  id: string;
  name?: string | null;
  email?: string | null;
  shop_name?: string | null;
  status?: string | null;
  rating?: number | null;
  product_count?: number;
  pickup_count?: number;
  payout_method_count?: number;
  verification_status?: string | null;
  rejection_reason?: string | null;
  suspension_reason?: string | null;
  submitted_for_review_at?: string | null;
  approved_at?: string | null;
};

type SellerDetailPayload = {
  user?: any;
  verification?: any;
  payout_methods?: any[];
  pickup_locations?: any[];
  products?: any[];
  seller_approval?: any;
};

const statusTone = (status?: string | null) => {
  if (status === 'approved') return 'bg-emerald-100 text-emerald-700';
  if (status === 'rejected' || status === 'suspended') return 'bg-rose-100 text-rose-700';
  if (status === 'pending_review' || status === 'under_review') return 'bg-amber-100 text-amber-700';
  return 'bg-slate-100 text-slate-700';
};

export const AdminSellersPage = () => {
  const { token } = useUser();
  const navigate = useNavigate();
  const [sellers, setSellers] = useState<SellerRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [selectedSellerId, setSelectedSellerId] = useState<string>('');
  const [selectedSeller, setSelectedSeller] = useState<SellerDetailPayload | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [reviewAction, setReviewAction] = useState<'approved' | 'rejected' | 'suspended' | 'under_review'>('approved');
  const [reviewReason, setReviewReason] = useState('');
  const [reviewSaving, setReviewSaving] = useState(false);

  const fetchSellers = async () => {
    if (!token) return;
    setLoading(true);
    setError('');
    try {
      const response = await fetch('/api/admin/sellers', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load sellers');
      }
      setSellers(Array.isArray(data) ? data : []);
    } catch (err) {
      setSellers([]);
      setError(err instanceof Error ? err.message : 'Failed to load sellers');
    } finally {
      setLoading(false);
    }
  };

  const fetchSellerDetail = async (sellerId: string) => {
    if (!token) return;
    setSelectedSellerId(sellerId);
    setDetailLoading(true);
    try {
      const response = await fetch(`/api/admin/users/${sellerId}/profile`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load seller detail');
      }
      setSelectedSeller(data);
      setReviewReason('');
      setReviewAction('approved');
    } catch (err) {
      setSelectedSeller(null);
      toast.error(err instanceof Error ? err.message : 'Failed to load seller detail');
    } finally {
      setDetailLoading(false);
    }
  };

  useEffect(() => {
    if (token) {
      void fetchSellers();
    }
  }, [token]);

  const filteredSellers = useMemo(
    () =>
      sellers.filter((seller) =>
        [seller.name, seller.shop_name, seller.email, seller.status]
          .filter(Boolean)
          .some((value) => String(value).toLowerCase().includes(search.toLowerCase())),
      ),
    [search, sellers],
  );

  const handleStatusChange = async () => {
    if (!selectedSellerId || !token) return;
    if ((reviewAction === 'rejected' || reviewAction === 'suspended') && reviewReason.trim().length < 5) {
      toast.error('Add a short reason before rejecting or suspending a seller.');
      return;
    }

    try {
      setReviewSaving(true);
      const response = await fetch(`/api/admin/sellers/${selectedSellerId}/status`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          status: reviewAction,
          reason: reviewReason.trim() || null,
        }),
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to update seller status');
      }
      toast.success(`Seller moved to ${reviewAction.replaceAll('_', ' ')}.`);
      await Promise.all([fetchSellers(), fetchSellerDetail(selectedSellerId)]);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status');
    } finally {
      setReviewSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
        <div>
          <h1 className="text-2xl font-bold">Seller Review Desk</h1>
          <p className="text-sm text-gray-500">Approve, reject, suspend, and audit every seller onboarding requirement from one admin workspace.</p>
        </div>
        <div className="relative w-full lg:w-72">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Search sellers..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-xl border border-gray-200 bg-white py-2 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/20"
          />
        </div>
      </div>

      <div className="grid gap-6 xl:grid-cols-[1.05fr_0.95fr]">
        <div className="table-responsive overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
          {error ? (
            <div className="border-b border-red-200 bg-red-50 px-6 py-3 text-sm text-red-700">
              {error}
            </div>
          ) : null}
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
                <th className="px-6 py-4">Store</th>
                <th className="px-6 py-4">Readiness</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredSellers.map((seller) => (
                <tr key={seller.id} className="text-sm transition-colors hover:bg-gray-50">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 text-primary">
                        <Store size={20} />
                      </div>
                      <div>
                        <p className="font-bold">{seller.shop_name || seller.name}</p>
                        <p className="text-xs text-gray-500">{seller.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="space-y-1 text-xs text-gray-500">
                      <p>{seller.product_count || 0} products</p>
                      <p>{seller.pickup_count || 0} pickup points</p>
                      <p>{seller.payout_method_count || 0} payout methods</p>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="space-y-2">
                      <span className={`inline-flex rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${statusTone(seller.status)}`}>
                        {String(seller.status || 'draft').replaceAll('_', ' ')}
                      </span>
                      <p className="text-xs text-gray-500">{seller.verification_status || 'no kyc'}</p>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2">
                      <button
                        onClick={() => void fetchSellerDetail(seller.id)}
                        className="p-2 text-gray-400 transition-colors hover:text-primary"
                        title="Open review panel"
                      >
                        <Eye size={18} />
                      </button>
                      <button
                        onClick={() => navigate(`/seller-profile/${seller.id}`)}
                        className="p-2 text-gray-400 transition-colors hover:text-gray-700"
                        title="Open public profile"
                      >
                        <ExternalLink size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredSellers.length === 0 ? (
                <tr>
                  <td colSpan={4} className="px-6 py-12 text-center text-sm text-gray-500">
                    {error ? 'No sellers available right now.' : 'No sellers found.'}
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>

        <div className="rounded-2xl border border-black/5 bg-white p-6 shadow-sm">
          {detailLoading ? (
            <div className="flex h-64 items-center justify-center">
              <Loader2 className="animate-spin text-primary" size={28} />
            </div>
          ) : selectedSeller ? (
            <div className="space-y-6">
              <div>
                <p className="section-kicker text-primary/70">Seller review</p>
                <h2 className="mt-2 text-xl font-bold text-slate-950">{selectedSeller.user?.store_name || selectedSeller.user?.name || 'Seller'}</h2>
                <p className="mt-1 text-sm text-slate-500">{selectedSeller.user?.email}</p>
              </div>

              <div className="grid gap-3 md:grid-cols-2">
                <div className="rounded-2xl border border-border bg-secondary/20 p-4">
                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Approval</p>
                  <p className="mt-2 text-sm font-semibold text-slate-950">
                    {String(selectedSeller.seller_approval?.status || 'draft').replaceAll('_', ' ')}
                  </p>
                  <p className="mt-1 text-xs text-slate-500">
                    {selectedSeller.seller_approval?.approved_at
                      ? `Approved ${new Date(selectedSeller.seller_approval.approved_at).toLocaleDateString()}`
                      : selectedSeller.seller_approval?.submitted_for_review_at
                        ? `Submitted ${new Date(selectedSeller.seller_approval.submitted_for_review_at).toLocaleDateString()}`
                        : 'Not submitted for review yet'}
                  </p>
                </div>
                <div className="rounded-2xl border border-border bg-secondary/20 p-4">
                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Verification</p>
                  <p className="mt-2 text-sm font-semibold text-slate-950">{selectedSeller.verification?.status || 'not submitted'}</p>
                  <p className="mt-1 text-xs text-slate-500">{selectedSeller.verification?.document_type || 'No KYC document yet'}</p>
                </div>
              </div>

              {selectedSeller.seller_approval?.rejection_reason ? (
                <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">
                  Rejection reason: {selectedSeller.seller_approval.rejection_reason}
                </div>
              ) : null}
              {selectedSeller.seller_approval?.suspension_reason ? (
                <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">
                  Suspension reason: {selectedSeller.seller_approval.suspension_reason}
                </div>
              ) : null}

              <div className="space-y-3">
                <h3 className="text-sm font-bold text-slate-950">Review actions</h3>
                <div className="flex flex-wrap gap-2">
                  {[
                    ['approved', 'Approve'],
                    ['under_review', 'Mark Under Review'],
                    ['rejected', 'Reject'],
                    ['suspended', 'Suspend'],
                  ].map(([value, label]) => (
                    <button
                      key={value}
                      type="button"
                      onClick={() => setReviewAction(value as typeof reviewAction)}
                      className={`rounded-full px-3 py-2 text-xs font-semibold transition ${
                        reviewAction === value ? 'bg-slate-950 text-white' : 'border border-border bg-white text-slate-600'
                      }`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
                <textarea
                  value={reviewReason}
                  onChange={(event) => setReviewReason(event.target.value)}
                  rows={3}
                  className="w-full rounded-2xl border border-border px-4 py-3 text-sm outline-none transition focus:border-primary"
                  placeholder="Add rejection or suspension reason when needed."
                />
                <button
                  type="button"
                  onClick={handleStatusChange}
                  disabled={reviewSaving}
                  className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
                >
                  {reviewSaving ? <Loader2 size={16} className="animate-spin" /> : reviewAction === 'approved' ? <CheckCircle size={16} /> : <ShieldAlert size={16} />}
                  Save seller review
                </button>
              </div>

              <div className="space-y-4">
                <section>
                  <h3 className="text-sm font-bold text-slate-950">KYC documents</h3>
                  <div className="mt-3 grid gap-3 md:grid-cols-2">
                    {(selectedSeller.verification?.documents || []).map((document: any) => (
                      <a
                        key={document.id}
                        href={document.file_url || '#'}
                        target="_blank"
                        rel="noreferrer"
                        className="rounded-2xl border border-border bg-secondary/20 p-4 text-sm text-slate-700"
                      >
                        <p className="font-semibold capitalize">{String(document.kind || 'document').replaceAll('_', ' ')}</p>
                        <p className="mt-1 text-xs text-muted-foreground">Open uploaded file</p>
                      </a>
                    ))}
                    {!selectedSeller.verification?.documents?.length ? (
                      <div className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground">
                        No KYC documents uploaded yet.
                      </div>
                    ) : null}
                  </div>
                </section>

                <section>
                  <h3 className="text-sm font-bold text-slate-950">Payout setup</h3>
                  <div className="mt-3 space-y-3">
                    {(selectedSeller.payout_methods || []).map((method: any) => (
                      <div key={method.id} className="rounded-2xl border border-border bg-secondary/20 p-4">
                        <p className="font-semibold text-slate-950">{method.provider || method.type || 'Payout method'}</p>
                        <p className="mt-1 text-xs text-muted-foreground">
                          {method.account_name || method.mobile_number || method.account_number || method.id}
                        </p>
                      </div>
                    ))}
                    {!selectedSeller.payout_methods?.length ? (
                      <div className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground">
                        No payout method configured yet.
                      </div>
                    ) : null}
                  </div>
                </section>

                <section>
                  <h3 className="text-sm font-bold text-slate-950">Pickup locations</h3>
                  <div className="mt-3 space-y-3">
                    {(selectedSeller.pickup_locations || []).map((pickup: any) => (
                      <div key={pickup.id} className="rounded-2xl border border-border bg-secondary/20 p-4">
                        <p className="font-semibold text-slate-950">{pickup.name || 'Pickup point'}</p>
                        <p className="mt-1 text-xs text-muted-foreground">
                          {[pickup.address, pickup.city, pickup.phone].filter(Boolean).join(' â€¢ ')}
                        </p>
                      </div>
                    ))}
                    {!selectedSeller.pickup_locations?.length ? (
                      <div className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground">
                        No pickup location added yet.
                      </div>
                    ) : null}
                  </div>
                </section>

                <section>
                  <h3 className="text-sm font-bold text-slate-950">Products</h3>
                  <div className="mt-3 space-y-3">
                    {(selectedSeller.products || []).slice(0, 8).map((product: any) => (
                      <div key={product.id} className="rounded-2xl border border-border bg-secondary/20 p-4">
                        <div className="flex items-center justify-between gap-3">
                          <div>
                            <p className="font-semibold text-slate-950">{product.name}</p>
                            <p className="mt-1 text-xs text-muted-foreground">
                              {product.product_status || 'draft'} â€¢ {formatPrice(Number(product.price || 0))}
                            </p>
                          </div>
                          <span className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wide ${statusTone(product.product_status === 'published' ? 'approved' : 'draft')}`}>
                            {product.product_status || 'draft'}
                          </span>
                        </div>
                      </div>
                    ))}
                    {!selectedSeller.products?.length ? (
                      <div className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground">
                        No products created yet.
                      </div>
                    ) : null}
                  </div>
                </section>
              </div>
            </div>
          ) : (
            <div className="flex h-full min-h-[320px] items-center justify-center rounded-2xl border border-dashed border-border text-sm text-muted-foreground">
              Select a seller to open the review panel.
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Search, Mail, Trash2, CheckCircle, Clock } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import toast from '@/lib/toast';
import { CenteredLoader, EmptyState, FormNotice } from '@/features/shared/ui/FeedbackState';
import { openMailto } from '../../../lib/browser-actions';

export const AdminSupportPage = () => {
  const { token } = useUser();
  const [messages, setMessages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [focusedMessageId, setFocusedMessageId] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);

  const fetchMessages = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await fetch('/api/admin/messages', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load support messages');
      }
      setMessages(data);
    } catch (err) {
      setMessages([]);
      setError(err instanceof Error ? err.message : 'Failed to load support messages');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) fetchMessages();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    const nextMessageId = params.get('message');

    if (nextSearch) {
      setSearch(nextSearch);
    }
    if (nextMessageId) {
      setFocusedMessageId(nextMessageId);
    }
  }, []);

  const handleStatusChange = async (id: number, status: string) => {
    try {
      const response = await fetch(`/api/admin/messages/${id}/status`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to update status');
      }
      toast.success(`Message marked as ${status}`);
      fetchMessages();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update status');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/admin/messages/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to delete message');
      }
      setDeleteConfirmId(null);
      toast.success('Message deleted');
      fetchMessages();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete message');
    }
  };

  const handleReplyByEmail = (email: string, subject: string) => {
    openMailto(email, `Re: ${subject}`);
  };

  const filteredMessages = messages.filter(m => 
    m.subject.toLowerCase().includes(search.toLowerCase()) ||
    m.name.toLowerCase().includes(search.toLowerCase()) ||
    m.email.toLowerCase().includes(search.toLowerCase())
  );

  useEffect(() => {
    if (!focusedMessageId || typeof window === 'undefined') return;

    const matched = filteredMessages.find((message) => String(message.id) === focusedMessageId);
    if (!matched) return;

    window.requestAnimationFrame(() => {
      document.getElementById(`admin-support-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [filteredMessages, focusedMessageId]);

  if (loading) {
    return <CenteredLoader label="Loading support messages..." className="min-h-[240px]" />;
  }

  return (
    <div className="space-y-6">
      {error ? <FormNotice tone="error">{error}</FormNotice> : null}
      <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold">Support Messages</h1>
          <p className="text-sm text-gray-500">Manage inquiries from the contact form</p>
        </div>
        <div className="relative w-full md:w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Search messages..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-xl border border-gray-200 bg-white py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/20 md:py-2" 
          />
        </div>
      </div>

      <div className="space-y-4">
        {filteredMessages.map((msg) => (
          <div
            id={`admin-support-${msg.id}`}
            key={msg.id}
                className={`rounded-2xl border bg-white p-4 md:p-6 ${
              String(msg.id) === focusedMessageId
                ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/40'
                : msg.status === 'unread'
                  ? 'border-primary/20 shadow-md shadow-primary/5'
                  : 'border-black/5 shadow-sm'
            } group flex flex-col gap-4 md:flex-row md:items-start md:space-x-4`}
          >
            <div className={`w-fit rounded-xl p-3 ${msg.status === 'unread' ? 'bg-primary/10 text-primary' : 'bg-gray-50 text-gray-400'}`}>
              <Mail size={24} />
            </div>
            <div className="flex-1">
              <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
                <div>
                  <h3 className="font-bold text-lg">{msg.subject}</h3>
                  <p className="text-sm text-gray-500 mb-2">From: <span className="font-bold text-gray-900">{msg.name}</span> ({msg.email})</p>
                </div>
                <div className="flex flex-wrap items-center gap-2">
                  {msg.status === 'unread' ? (
                    <button 
                      onClick={() => handleStatusChange(msg.id, 'read')}
                      className="p-2 text-primary hover:bg-primary/5 rounded-lg transition-colors"
                      title="Mark as Read"
                    >
                      <CheckCircle size={18} />
                    </button>
                  ) : (
                    <button 
                      onClick={() => handleStatusChange(msg.id, 'unread')}
                      className="p-2 text-gray-400 hover:bg-gray-100 rounded-lg transition-colors"
                      title="Mark as Unread"
                    >
                      <Clock size={18} />
                    </button>
                  )}
                  <button 
                    onClick={() => handleReplyByEmail(msg.email, msg.subject)}
                    className="p-2 text-gray-400 hover:text-primary hover:bg-primary/5 rounded-lg transition-colors"
                    title="Reply by Email"
                  >
                    <Mail size={18} />
                  </button>
                  {deleteConfirmId === msg.id ? (
                    <div className="flex items-center gap-2 rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700">
                      <span>Delete?</span>
                      <button
                        onClick={() => handleDelete(msg.id)}
                        className="rounded-lg bg-rose-600 px-2.5 py-1 text-white transition hover:bg-rose-700"
                      >
                        Confirm
                      </button>
                      <button
                        onClick={() => setDeleteConfirmId(null)}
                        className="rounded-lg border border-slate-200 bg-white px-2.5 py-1 text-slate-600 transition hover:bg-slate-50"
                      >
                        Cancel
                      </button>
                    </div>
                  ) : (
                    <button 
                      onClick={() => setDeleteConfirmId(msg.id)}
                      className="p-2 text-gray-400 hover:text-accent hover:bg-accent/5 rounded-lg transition-colors"
                      title="Delete Message"
                    >
                      <Trash2 size={18} />
                    </button>
                  )}
                </div>
              </div>
              <div className="bg-gray-50 p-4 rounded-xl mt-4">
                <p className="text-sm text-gray-700 whitespace-pre-wrap">{msg.message}</p>
              </div>
              <p className="text-[10px] text-gray-400 mt-4 uppercase tracking-wider">
                Received on {new Date(msg.created_at).toLocaleString()}
              </p>
            </div>
          </div>
        ))}
        {filteredMessages.length === 0 ? (
          <EmptyState
            icon={<Mail size={24} />}
            title={search ? 'No messages match this search' : 'No support messages yet'}
            description={
              search
                ? 'Try a different subject, sender name, or email address.'
                : 'New contact form submissions and support requests will appear here.'
            }
            tone="soft"
            className="py-12"
          />
        ) : null}
      </div>
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { Ban, Search, Shield, ShieldCheck, Trash2 } from 'lucide-react';
import toast from '@/lib/toast';
import { useUser } from '../../../features/shared/state/UserContext';
import { CenteredLoader, EmptyState } from '@/features/shared/ui/FeedbackState';

interface AdminUserRecord {
  id: string;
  name?: string | null;
  email?: string | null;
  role: 'admin' | 'seller' | 'reseller' | 'customer';
  verification_status?: string | null;
  is_blocked?: boolean;
  created_at?: string;
}

export const AdminUsersPage = () => {
  const { token, user: currentUser } = useUser();
  const [users, setUsers] = useState<AdminUserRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [focusedUserId, setFocusedUserId] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState('');

  const fetchUsers = async () => {
    try {
      const response = await fetch('/api/admin/users', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load users');
      }

      setUsers(Array.isArray(data) ? data : []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load users');
      setUsers([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) {
      void fetchUsers();
    }
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    const nextUser = params.get('user');

    if (nextSearch) {
      setSearch(nextSearch);
    }
    if (nextUser) {
      setFocusedUserId(nextUser);
    }
  }, []);

  const handleRoleChange = async (id: string, newRole: AdminUserRecord['role']) => {
    try {
      const response = await fetch(`/api/admin/users/${id}/role`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ role: newRole }),
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to update role');
      }

      toast.success(`User role updated to ${newRole}`);
      await fetchUsers();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update role');
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/admin/users/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to delete user');
      }

      setDeleteConfirmId('');
      toast.success('User deleted');
      await fetchUsers();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete user');
    }
  };

  const handleBlockToggle = async (id: string, shouldBlock: boolean) => {
    try {
      const endpoint = shouldBlock ? 'block' : 'unblock';
      const response = await fetch(`/api/admin/users/${id}/${endpoint}`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ reason: shouldBlock ? 'Admin review action' : undefined }),
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to update user status');
      }

      toast.success(shouldBlock ? 'User blocked' : 'User unblocked');
      await fetchUsers();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update user status');
    }
  };

  const filteredUsers = useMemo(() => {
    const normalizedSearch = search.trim().toLowerCase();
    if (!normalizedSearch) return users;

    return users.filter((entry) => {
      const name = entry.name?.toLowerCase() || '';
      const email = entry.email?.toLowerCase() || '';
      return (
        name.includes(normalizedSearch) ||
        email.includes(normalizedSearch) ||
        entry.id.toLowerCase().includes(normalizedSearch)
      );
    });
  }, [search, users]);

  useEffect(() => {
    if (!focusedUserId || typeof window === 'undefined') return;

    window.requestAnimationFrame(() => {
      document.getElementById(`admin-user-${focusedUserId}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [filteredUsers.length, focusedUserId]);

  if (loading) {
    return <CenteredLoader label="Loading users..." className="min-h-[240px]" />;
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <h1 className="text-2xl font-bold">User Management</h1>
        <div className="relative w-full md:w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Search users..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-xl border border-gray-200 bg-white py-3 pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary/20 md:py-2"
          />
        </div>
      </div>

      <div className="overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
        <div className="space-y-3 p-4 md:hidden">
          {filteredUsers.length === 0 ? (
            <EmptyState
              icon={<Search size={24} />}
              title={search ? 'No users match this search' : 'No users found'}
              description={
                search
                  ? 'Try a different name, email, or user ID.'
                  : 'Users will appear here once people start registering on the marketplace.'
              }
              tone="soft"
              className="py-12"
            />
          ) : filteredUsers.map((entry) => {
            const isSelf = currentUser?.id === entry.id;
            return (
              <div
                id={`admin-user-${entry.id}`}
                key={entry.id}
                className={`rounded-2xl border p-4 shadow-sm ${
                  entry.id === focusedUserId ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30' : 'border-slate-200 bg-white'
                }`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p className="font-bold text-slate-900">
                      {entry.name || 'Unnamed user'}
                      {isSelf ? <span className="ml-2 text-xs font-semibold text-primary">(You)</span> : null}
                    </p>
                    <p className="mt-1 text-xs text-gray-500">{entry.email || 'No email available'}</p>
                  </div>
                  <span
                    className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                      entry.is_blocked ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'
                    }`}
                  >
                    {entry.is_blocked ? 'blocked' : 'active'}
                  </span>
                </div>
                <div className="mt-3 flex flex-wrap gap-2">
                  <span
                    className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                      entry.role === 'admin'
                        ? 'bg-purple-100 text-purple-800'
                        : entry.role === 'seller'
                          ? 'bg-blue-100 text-blue-800'
                          : entry.role === 'reseller'
                            ? 'bg-orange-100 text-orange-800'
                            : 'bg-gray-100 text-gray-800'
                    }`}
                  >
                    {entry.role}
                  </span>
                  <span
                    className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                      entry.verification_status === 'verified'
                        ? 'bg-green-100 text-green-800'
                        : entry.verification_status === 'rejected'
                          ? 'bg-red-100 text-red-800'
                          : 'bg-amber-100 text-amber-800'
                    }`}
                  >
                    {entry.verification_status || 'not_submitted'}
                  </span>
                </div>
                <p className="mt-3 text-xs text-gray-500">
                  Joined {entry.created_at ? new Date(entry.created_at).toLocaleDateString() : 'N/A'}
                </p>
                <div className="mt-4 space-y-3">
                  <select
                    className="w-full rounded-xl border border-gray-200 px-3 py-3 text-sm outline-none focus:ring-1 focus:ring-primary disabled:cursor-not-allowed disabled:opacity-40"
                    value={entry.role}
                    disabled={isSelf}
                    onChange={(e) => handleRoleChange(entry.id, e.target.value as AdminUserRecord['role'])}
                  >
                    <option value="customer">Customer</option>
                    <option value="seller">Seller</option>
                    <option value="reseller">Reseller</option>
                    <option value="admin">Admin</option>
                  </select>
                  <div className="grid grid-cols-3 gap-2">
                    <button
                      onClick={() => handleBlockToggle(entry.id, !entry.is_blocked)}
                      disabled={isSelf}
                      className={`rounded-xl border p-3 transition-colors disabled:cursor-not-allowed disabled:opacity-40 ${
                        entry.is_blocked ? 'text-green-600' : 'text-rose-600'
                      }`}
                    >
                      {entry.is_blocked ? <ShieldCheck size={16} className="mx-auto" /> : <Ban size={16} className="mx-auto" />}
                    </button>
                    <button
                      onClick={() => handleRoleChange(entry.id, 'admin')}
                      disabled={entry.role === 'admin' || isSelf}
                      className="rounded-xl border p-3 text-purple-600 transition-colors disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      <Shield size={16} className="mx-auto" />
                    </button>
                    <button
                      onClick={() => setDeleteConfirmId((current) => (current === entry.id ? '' : entry.id))}
                      disabled={isSelf}
                      className="rounded-xl border p-3 text-rose-600 transition-colors disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      <Trash2 size={16} className="mx-auto" />
                    </button>
                  </div>
                  {!isSelf && deleteConfirmId === entry.id ? (
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="text-xs font-medium text-rose-700">Delete this user?</span>
                      <button
                        onClick={() => handleDelete(entry.id)}
                        className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-rose-700"
                      >
                        Confirm
                      </button>
                      <button
                        onClick={() => setDeleteConfirmId('')}
                        className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition hover:bg-slate-50"
                      >
                        Cancel
                      </button>
                    </div>
                  ) : null}
                </div>
              </div>
            );
          })}
        </div>
        <div className="table-responsive hidden md:block">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
              <th className="px-6 py-4">User</th>
              <th className="px-6 py-4">Role</th>
              <th className="px-6 py-4">Verification</th>
              <th className="px-6 py-4">Status</th>
              <th className="px-6 py-4">Joined</th>
              <th className="px-6 py-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filteredUsers.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-6 py-10">
                  <EmptyState
                    icon={<Search size={24} />}
                    title={search ? 'No users match this search' : 'No users found'}
                    description={
                      search
                        ? 'Try a different name, email, or user ID.'
                        : 'Users will appear here once people start registering on the marketplace.'
                    }
                    tone="soft"
                    className="py-10"
                  />
                </td>
              </tr>
            ) : filteredUsers.map((entry) => {
              const isSelf = currentUser?.id === entry.id;

              return (
                <tr
                  id={`admin-user-${entry.id}`}
                  key={entry.id}
                  className={`text-sm transition-colors hover:bg-gray-50 ${
                    entry.id === focusedUserId ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200' : ''
                  }`}
                >
                  <td className="px-6 py-4">
                    <div>
                      <p className="font-bold">
                        {entry.name || 'Unnamed user'}
                        {isSelf && <span className="ml-2 text-xs font-semibold text-primary">(You)</span>}
                      </p>
                      <p className="text-xs text-gray-500">{entry.email || 'No email available'}</p>
                    </div>
                  </td>
                  <td className="px-6 py-4 capitalize">
                    <span
                      className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                        entry.role === 'admin'
                          ? 'bg-purple-100 text-purple-800'
                          : entry.role === 'seller'
                            ? 'bg-blue-100 text-blue-800'
                            : entry.role === 'reseller'
                              ? 'bg-orange-100 text-orange-800'
                              : 'bg-gray-100 text-gray-800'
                      }`}
                    >
                      {entry.role}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                        entry.verification_status === 'verified'
                          ? 'bg-green-100 text-green-800'
                          : entry.verification_status === 'rejected'
                            ? 'bg-red-100 text-red-800'
                            : 'bg-amber-100 text-amber-800'
                      }`}
                    >
                      {entry.verification_status || 'not_submitted'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                        entry.is_blocked ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'
                      }`}
                    >
                      {entry.is_blocked ? 'blocked' : 'active'}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-gray-500">
                    {entry.created_at ? new Date(entry.created_at).toLocaleDateString() : 'N/A'}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end space-x-2">
                      {entry.role !== 'admin' && !isSelf && (
                        <button
                          onClick={() => handleRoleChange(entry.id, 'admin')}
                          className="p-2 text-gray-400 transition-colors hover:text-purple-600"
                          title="Make Admin"
                        >
                          <Shield size={18} />
                        </button>
                      )}
                      <button
                        onClick={() => handleBlockToggle(entry.id, !entry.is_blocked)}
                        disabled={isSelf}
                        className={`p-2 transition-colors ${
                          entry.is_blocked ? 'text-green-600 hover:text-green-700' : 'text-gray-400 hover:text-red-600'
                        } disabled:cursor-not-allowed disabled:opacity-40`}
                        title={isSelf ? 'You cannot block your own account' : entry.is_blocked ? 'Unblock user' : 'Block user'}
                      >
                        {entry.is_blocked ? <ShieldCheck size={18} /> : <Ban size={18} />}
                      </button>
                      <select
                        className="rounded-lg border border-gray-200 px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-primary disabled:cursor-not-allowed disabled:opacity-40"
                        value={entry.role}
                        disabled={isSelf}
                        onChange={(e) => handleRoleChange(entry.id, e.target.value as AdminUserRecord['role'])}
                      >
                        <option value="customer">Customer</option>
                        <option value="seller">Seller</option>
                        <option value="reseller">Reseller</option>
                        <option value="admin">Admin</option>
                      </select>
                      <button
                        onClick={() => setDeleteConfirmId((current) => (current === entry.id ? '' : entry.id))}
                        disabled={isSelf}
                        className="p-2 text-gray-400 transition-colors hover:text-accent disabled:cursor-not-allowed disabled:opacity-40"
                        title={isSelf ? 'You cannot delete your own account here' : 'Delete User'}
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                    {!isSelf && deleteConfirmId === entry.id ? (
                      <div className="mt-2 flex items-center justify-end gap-2">
                        <span className="text-xs font-medium text-rose-700">Delete this user?</span>
                        <button
                          onClick={() => handleDelete(entry.id)}
                          className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-rose-700"
                        >
                          Confirm
                        </button>
                        <button
                          onClick={() => setDeleteConfirmId('')}
                          className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition hover:bg-slate-50"
                        >
                          Cancel
                        </button>
                      </div>
                    ) : null}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  AlertCircle,
  CheckCircle,
  Lightbulb,
  Mic,
  MicOff,
  Search as SearchIcon,
  Volume2,
} from 'lucide-react';
import { useVoiceSearch } from '@/features/ai/hooks/useVoiceSearch';

interface VoiceSearchProps {
  onSearch?: (query: string) => void;
  placeholder?: string;
}

const exampleQueries = [
  'Show me blue running shoes',
  'Find winter jackets under 5000 taka',
  'Look for wireless earbuds with good battery life',
  'Search for black panjabi for Eid',
];

export const VoiceSearch: React.FC<VoiceSearchProps> = ({
  onSearch,
  placeholder = "Say what you're looking for...",
}) => {
  const { isListening, transcript, confidence, error, startListening, stopListening, resetTranscript, isSupported } =
    useVoiceSearch();

  const [searchResults, setSearchResults] = useState<string[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  const handleStartListening = () => {
    resetTranscript();
    startListening();
  };

  const handleStopListening = () => {
    stopListening();
  };

  const handleSearch = (query: string) => {
    const trimmedQuery = query.trim();
    if (!trimmedQuery) return;

    setSearchQuery(trimmedQuery);
    onSearch?.(trimmedQuery);

    setSearchResults([
      `Ready to search for "${trimmedQuery}"`,
      'Matching products across the storefront',
      'Relevant categories and trending results',
      'Filters you can refine after search',
    ]);
  };

  const handleUseTranscript = () => {
    if (!transcript) return;
    handleSearch(transcript);
    handleStopListening();
  };

  useEffect(() => {
    if (transcript && transcript.length > 3 && !isListening) {
      const timer = window.setTimeout(() => {
        if (transcript && !isListening) {
          handleSearch(transcript);
        }
      }, 500);

      return () => window.clearTimeout(timer);
    }
  }, [isListening, transcript]);

  if (!isSupported) {
    return (
      <div className="flex gap-3 rounded-lg border border-yellow-400 bg-yellow-100 px-6 py-4 text-yellow-800">
        <AlertCircle className="h-5 w-5 flex-shrink-0" />
        <div>
          <p className="font-semibold">Voice Search Not Supported</p>
          <p className="text-sm">Your browser does not support voice recognition. Please use Chrome, Edge, or Safari.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full space-y-4">
      <div className="space-y-3">
        <div className="flex gap-3">
          <button
            type="button"
            onClick={isListening ? handleStopListening : handleStartListening}
            className={`flex flex-1 items-center justify-center gap-2 rounded-lg px-4 py-4 text-lg font-semibold transition-all ${
              isListening
                ? 'animate-pulse bg-red-600 text-white hover:bg-red-700'
                : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            {isListening ? (
              <>
                <MicOff className="h-6 w-6" />
                Stop Listening
              </>
            ) : (
              <>
                <Mic className="h-6 w-6" />
                Start Listening
              </>
            )}
          </button>

          <button
            type="button"
            onClick={() => handleSearch(exampleQueries[0])}
            className="flex items-center gap-2 rounded-lg bg-gray-100 px-6 py-4 font-semibold transition-colors hover:bg-gray-200"
          >
            <Volume2 className="h-5 w-5" />
            <span className="hidden sm:inline">Try Example</span>
          </button>
        </div>

        <div className="rounded-2xl border border-gray-200 bg-white p-4">
          <div className="flex items-center gap-2 text-sm font-semibold text-gray-900">
            <SearchIcon className="h-4 w-4 text-primary" />
            Voice query ideas
          </div>
          <p className="mt-2 text-sm text-gray-500">{placeholder}</p>
          <div className="mt-3 flex flex-wrap gap-2">
            {exampleQueries.map((example) => (
              <button
                key={example}
                type="button"
                onClick={() => handleSearch(example)}
                className="rounded-full bg-gray-100 px-3 py-2 text-xs font-medium text-gray-700 transition-colors hover:bg-gray-200"
              >
                {example}
              </button>
            ))}
          </div>
        </div>

        <AnimatePresence>
          {transcript && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="rounded-lg border border-blue-200 bg-blue-50 p-4"
            >
              <div className="flex items-start gap-3">
                <div className="flex-1">
                  <p className="text-sm font-medium text-gray-600">You said:</p>
                  <p className="mt-1 text-lg text-gray-900">{transcript}</p>
                  <div className="mt-2 flex items-center gap-2">
                    <div className="h-2 flex-1 rounded-full bg-gray-200">
                      <div
                        className="h-2 rounded-full bg-blue-600 transition-all duration-300"
                        style={{ width: `${confidence * 100}%` }}
                      />
                    </div>
                    <span className="text-xs font-medium text-gray-600">{Math.round(confidence * 100)}%</span>
                  </div>
                </div>
              </div>

              {isListening ? (
                <div className="mt-3 flex gap-1">
                  {[0, 1, 2].map((i) => (
                    <div
                      key={i}
                      className="h-8 flex-1 animate-pulse rounded bg-blue-400"
                      style={{ animationDelay: `${i * 100}ms` }}
                    />
                  ))}
                </div>
              ) : (
                <div className="mt-3 flex gap-2">
                  <button
                    type="button"
                    onClick={handleUseTranscript}
                    className="flex-1 rounded-lg bg-blue-600 px-4 py-2 font-medium text-white transition-colors hover:bg-blue-700"
                  >
                    Search
                  </button>
                  <button
                    type="button"
                    onClick={resetTranscript}
                    className="flex-1 rounded-lg bg-gray-300 px-4 py-2 font-medium text-gray-900 transition-colors hover:bg-gray-400"
                  >
                    Clear
                  </button>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {isListening ? (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex items-center justify-center gap-2 font-medium text-red-600">
            <span className="h-2 w-2 animate-pulse rounded-full bg-red-600" />
            Listening...
          </motion.div>
        ) : null}

        <AnimatePresence>
          {error ? (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="flex gap-2 rounded-lg border border-red-400 bg-red-100 px-4 py-3 text-red-700"
            >
              <AlertCircle className="h-5 w-5 flex-shrink-0" />
              <p>{error}</p>
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>

      {searchResults.length > 0 ? (
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="border-t pt-4">
          <div className="mb-4 flex items-center gap-2">
            <CheckCircle className="h-5 w-5 text-green-600" />
            <p className="font-semibold text-gray-900">{searchResults[0]}</p>
          </div>

          <div className="space-y-2">
            {searchResults.slice(1).map((result, idx) => (
              <motion.div
                key={result}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: idx * 0.1 }}
                className="rounded-lg bg-gray-50 px-4 py-3 font-medium text-gray-700"
              >
                {result}
              </motion.div>
            ))}
          </div>
        </motion.div>
      ) : null}

      <div className="space-y-3 rounded-lg bg-gray-50 p-4">
        <div className="flex items-center gap-2 text-sm font-semibold text-gray-900">
          <Lightbulb className="h-4 w-4 text-amber-500" />
          Voice search tips
        </div>
        <ul className="space-y-2 text-sm text-gray-700">
          <li>Say clear, natural phrases like "Show me blue running shoes".</li>
          <li>Mention product type, color, budget, or brand for better search quality.</li>
          <li>Speak at a steady pace and wait a moment before stopping the microphone.</li>
          <li>One focused request works better than multiple requests in the same command.</li>
        </ul>
        {searchQuery ? (
          <p className="text-xs text-gray-500">
            Latest query: <span className="font-semibold text-gray-700">{searchQuery}</span>
          </p>
        ) : null}
      </div>
    </div>
  );
};

export default VoiceSearch;

import React, { useEffect, useMemo, useState } from 'react';
import { Bell, Coins, Package, ShieldCheck, Tag, Wallet, BadgeCheck, Users, Zap } from 'lucide-react';
import { motion } from 'framer-motion';
import toast from '@/lib/toast';
import { useUser } from '../../../features/shared/state/UserContext';
import { Link, useNavigate } from '../../../lib/navigation';
import { CenteredLoader, EmptyState } from '@/features/shared/ui/FeedbackState';

type NotificationItem = {
  id: string;
  type: string;
  title: string;
  message: string;
  action_url?: string | null;
  read_at?: string | null;
  created_at: string;
};

const iconByType: Record<string, React.ReactNode> = {
  order_update: <Package className="h-5 w-5" />,
  reward: <Coins className="h-5 w-5" />,
  security: <ShieldCheck className="h-5 w-5" />,
  marketing: <Tag className="h-5 w-5" />,
  inventory: <Package className="h-5 w-5" />,
  payout: <Wallet className="h-5 w-5" />,
  verification: <BadgeCheck className="h-5 w-5" />,
  community: <Users className="h-5 w-5" />,
  flash_sale: <Zap className="h-5 w-5" />,
  account_action: <ShieldCheck className="h-5 w-5" />,
};

export const CustomerNotificationsPage = () => {
  const { token } = useUser();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [items, setItems] = useState<NotificationItem[]>([]);
  const [focusedNotificationId, setFocusedNotificationId] = useState('');
  const unreadCount = items.filter((item) => !item.read_at).length;

  const loadNotifications = (options?: { silent?: boolean }) => {
    if (!token) {
      return;
    }

    if (!options?.silent) {
      setLoading(true);
    }
    const requestUrl = `/api/notifications?ts=${Date.now()}`;
    fetch(requestUrl, {
      headers: {
        Authorization: `Bearer ${token}`,
        'Cache-Control': 'no-cache',
        Pragma: 'no-cache',
      },
      cache: 'no-store',
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error('Failed to load notifications');
        }
        return res.json();
      })
      .then((data) => setItems(Array.isArray(data) ? data : []))
      .finally(() => {
        if (!options?.silent) {
          setLoading(false);
        }
      });
  };

  useEffect(() => {
    loadNotifications();
  }, [token]);

  useEffect(() => {
    if (!token) {
      return;
    }

    const intervalId = window.setInterval(() => {
      loadNotifications({ silent: true });
    }, 60000);

    return () => {
      window.clearInterval(intervalId);
    };
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextNotification = params.get('notification');

    if (nextNotification) {
      setFocusedNotificationId(nextNotification);
    }
  }, []);

  const markAllRead = async () => {
    if (!token) {
      return;
    }

    const response = await fetch('/api/notifications/read-all', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      toast.error('Could not update notifications right now.');
      return;
    }

    setItems((current) => current.map((item) => ({ ...item, read_at: new Date().toISOString() })));
    toast.success('Notifications marked as read.');
  };

  const markNotificationRead = async (notificationId: string) => {
    if (!token) {
      return false;
    }

    const response = await fetch(`/api/notifications/${notificationId}/read`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      toast.error('Could not update this notification right now.');
      return false;
    }

    setItems((current) =>
      current.map((item) =>
        item.id === notificationId ? { ...item, read_at: item.read_at || new Date().toISOString() } : item,
      ),
    );
    return true;
  };

  const openNotification = async (item: NotificationItem) => {
    if (!item.read_at) {
      await markNotificationRead(item.id);
    }

    if (item.action_url) {
      navigate(item.action_url);
    }
  };

  const filteredItems = useMemo(() => items, [items]);

  useEffect(() => {
    if (!focusedNotificationId || typeof window === 'undefined') return;

    const matched = filteredItems.find((item) => item.id === focusedNotificationId);
    if (!matched) return;

    window.requestAnimationFrame(() => {
      document.getElementById(`customer-notification-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [filteredItems, focusedNotificationId]);

  if (loading) {
    return <CenteredLoader label="Loading your latest notifications..." />;
  }

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Notifications</h1>
          <p className="text-gray-500">Order updates, reward unlocks, security alerts, and recovery nudges all live here.</p>
        </div>
        <div className="flex items-center gap-3">
          {unreadCount > 0 ? (
            <span className="rounded-full bg-primary/10 px-3 py-1 text-sm font-semibold text-primary">
              {unreadCount} unread
            </span>
          ) : null}
          <button onClick={markAllRead} className="text-sm font-semibold text-primary hover:underline">
            Mark all as read
          </button>
        </div>
      </div>

      <div className="overflow-hidden rounded-3xl border border-gray-100 bg-white shadow-sm">
        {filteredItems.length === 0 ? (
          <EmptyState
            className="rounded-none border-0 shadow-none"
            tone="soft"
            icon={<Bell className="h-8 w-8" />}
            title={items.length === 0 ? 'No notifications yet' : 'No notifications in this filter'}
            description={
              items.length === 0
                ? 'New order events, reward activity, and admin review updates will appear here.'
                : 'Try switching filters to view other notification categories.'
            }
          />
        ) : (
          <div className="max-h-[25rem] overflow-y-auto divide-y divide-gray-100 md:max-h-[31rem]">
            {filteredItems.map((item, index) => (
              <motion.div
                id={`customer-notification-${item.id}`}
                key={item.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.04 }}
                className={`flex gap-4 px-6 py-5 ${
                  item.id === focusedNotificationId
                    ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200'
                    : item.read_at
                      ? 'bg-white'
                      : 'bg-primary/5'
                }`}
              >
                <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-slate-100 text-slate-700">
                  {iconByType[item.type] ?? <Bell className="h-5 w-5" />}
                </div>
                <div className="flex-1">
                  <div className="mb-1 flex items-center justify-between gap-4">
                    <h3 className="font-semibold text-gray-950">{item.title}</h3>
                    <span className="text-xs text-gray-400">{new Date(item.created_at).toLocaleString()}</span>
                  </div>
                  <p className="text-sm leading-6 text-gray-600">{item.message}</p>
                  <div className="mt-3 flex flex-wrap items-center gap-3">
                    {item.action_url ? (
                      <button
                        type="button"
                        onClick={() => void openNotification(item)}
                        className="text-sm font-semibold text-primary hover:text-primary-dark"
                      >
                        Open
                      </button>
                    ) : null}
                    {!item.read_at ? (
                      <button
                        type="button"
                        onClick={() => void markNotificationRead(item.id)}
                        className="text-sm font-semibold text-slate-600 hover:text-slate-900"
                      >
                        Mark as read
                      </button>
                    ) : null}
                    {item.action_url ? (
                      <Link to={item.action_url} className="text-xs text-slate-400 hover:text-slate-600">
                        {item.action_url}
                      </Link>
                    ) : null}
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

