              <Link
                to={step.action_path}
                className="inline-flex items-center gap-2 rounded-full border border-border px-4 py-2 text-xs font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
              >
                Open
                <ArrowRight size={14} />
              </Link>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default SellerOnboardingPage;

import React, { useEffect, useMemo, useState } from 'react';
import { ArrowUpRight, CreditCard, Loader2, Wallet } from 'lucide-react';
import toast from '@/lib/toast';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';

type PayoutMethod = {
  id: string;
  provider?: string | null;
  type?: string | null;
  account_name?: string | null;
  account_number?: string | null;
  mobile_number?: string | null;
  is_default?: boolean;
};

type PayoutTransaction = {
  id: string;
  amount: number;
  status: string;
  created_at?: string;
  notes?: string | null;
};

type EarningsResponse = {
  totalEarnings: number;
  transactions: Array<{ amount: number; status: string }>;
};

export const SellerPayoutsPage = () => {
  const { token, user } = useUser();
  const sellerApproved = user?.seller_status === 'approved';
  const [methods, setMethods] = useState<PayoutMethod[]>([]);
  const [transactions, setTransactions] = useState<PayoutTransaction[]>([]);
  const [availableBalance, setAvailableBalance] = useState(0);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [form, setForm] = useState({ amount: '', payout_method_id: '', notes: '' });

  const loadData = async () => {
    if (!token) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError('');

    try {
      const [profileRes, earningsRes] = await Promise.all([
        fetch('/api/users/profile', { headers: { Authorization: `Bearer ${token}` } }),
        fetch('/api/seller/earnings', { headers: { Authorization: `Bearer ${token}` } }),
      ]);

      const profilePayload = await profileRes.json().catch(() => null);
      const earningsPayload = (await earningsRes.json().catch(() => null)) as EarningsResponse | null;

      if (!profileRes.ok) throw new Error(profilePayload?.error || 'Failed to load payout setup');
      if (!earningsRes.ok) throw new Error((earningsPayload as any)?.error || 'Failed to load payout balance');

      const nextMethods = Array.isArray(profilePayload?.payout_methods) ? profilePayload.payout_methods : [];
      const nextTransactions = Array.isArray(profilePayload?.transaction_history) ? profilePayload.transaction_history : [];
      const earningsTransactions = Array.isArray(earningsPayload?.transactions) ? earningsPayload.transactions : [];
      const pendingClearance = earningsTransactions
        .filter((transaction) => String(transaction.status || '').toLowerCase() !== 'delivered')
        .reduce((sum, transaction) => sum + Number(transaction.amount || 0), 0);

      setMethods(nextMethods);
      setTransactions(nextTransactions);
      setAvailableBalance(Math.max(0, Number(earningsPayload?.totalEarnings || 0) - pendingClearance));
      setForm((current) => ({
        ...current,
        payout_method_id: current.payout_method_id || nextMethods.find((method: PayoutMethod) => method.is_default)?.id || nextMethods[0]?.id || '',
      }));
    } catch (requestError: unknown) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to load payouts.');
      setMethods([]);
      setTransactions([]);
      setAvailableBalance(0);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadData();
  }, [token]);

  const pendingRequests = useMemo(
    () =>
      transactions
        .filter((transaction) => String(transaction.status || '').toLowerCase() === 'pending')
        .reduce((sum, transaction) => sum + Number(transaction.amount || 0), 0),
    [transactions],
  );

  const submitRequest = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!token) return;

    const amount = Number(form.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      toast.error('Enter a valid payout amount.');
      return;
    }

    setSubmitting(true);
    setError('');

    try {
      const response = await fetch('/api/users/payout-request', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          amount,
          payout_method_id: form.payout_method_id || null,
          notes: form.notes || null,
        }),
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) throw new Error(payload?.error || 'Failed to submit payout request');
      toast.success('Payout request submitted.');
      setForm((current) => ({ ...current, amount: '', notes: '' }));
      await loadData();
    } catch (requestError: unknown) {
      const nextError = requestError instanceof Error ? requestError.message : 'Failed to submit payout request.';
      setError(nextError);
      toast.error(nextError);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {error ? <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error}</div> : null}
      {!sellerApproved ? (
        <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          Payout withdrawals stay locked until admin approves your seller account. You can still configure payout methods from seller settings.
        </div>
      ) : null}

      <SellerPageHeader
        eyebrow="Finance operations"
        title="Payouts"
        description="Request withdrawals, review payout methods, and track settlement history from one seller finance screen."
      />

      <div className="grid gap-4 md:grid-cols-3">
        <SellerStatCard label="Available" value={formatPrice(availableBalance)} />
        <SellerStatCard label="Pending requests" value={formatPrice(pendingRequests)} tone="warning" />
        <SellerStatCard label="Methods" value={methods.length} />
      </div>

      <div className="grid gap-6 xl:grid-cols-[0.92fr_1.08fr]">
        <section className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
          <h2 className="text-lg font-bold text-slate-950">Request a payout</h2>
          <p className="mt-1 text-sm text-slate-500">Send a live payout request to the currently configured seller payout backend.</p>
          <form onSubmit={submitRequest} className="mt-6 space-y-4">
            <label className="block">
              <span className="mb-1 block text-sm font-medium text-slate-700">Amount</span>
              <input
                type="number"
                min="1"
                step="0.01"
                value={form.amount}
                onChange={(event) => setForm((current) => ({ ...current, amount: event.target.value }))}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm outline-none transition focus:border-primary"
                placeholder="1500"
              />
            </label>
            <label className="block">
              <span className="mb-1 block text-sm font-medium text-slate-700">Payout method</span>
              <select
                value={form.payout_method_id}
                onChange={(event) => setForm((current) => ({ ...current, payout_method_id: event.target.value }))}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm outline-none transition focus:border-primary"
              >
                <option value="">Use default account</option>
                {methods.map((method) => (
                  <option key={method.id} value={method.id}>
                    {method.provider || method.type || 'Payout method'} â€¢ {method.account_name || method.mobile_number || method.account_number || method.id}
                  </option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="mb-1 block text-sm font-medium text-slate-700">Notes</span>
              <textarea
                value={form.notes}
                onChange={(event) => setForm((current) => ({ ...current, notes: event.target.value }))}
                className="min-h-[120px] w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm outline-none transition focus:border-primary"
                placeholder="Optional note for finance team"
              />
            </label>
            <button type="submit" disabled={submitting || !sellerApproved} className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60">
              {submitting ? <Loader2 size={16} className="animate-spin" /> : <Wallet size={16} />}
              Submit payout request
            </button>
          </form>
        </section>

        <section className="space-y-6">
          <div className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
            <div className="flex items-center gap-3">
              <CreditCard size={18} className="text-primary" />
              <h2 className="text-lg font-bold text-slate-950">Configured payout methods</h2>
            </div>
            <div className="mt-5 space-y-3">
              {methods.length === 0 ? (
                <SellerEmptyState message="No payout method found yet. Add one from seller settings before requesting withdrawals." />
              ) : (
                methods.map((method) => (
                  <div key={method.id} className="rounded-2xl border border-slate-200 px-4 py-4">
                    <div className="flex items-center justify-between gap-4">
                      <div>
                        <p className="font-semibold text-slate-900">{method.provider || method.type || 'Payout method'}</p>
                        <p className="mt-1 text-xs text-slate-500">{method.account_name || method.mobile_number || method.account_number || method.id}</p>
                      </div>
                      {method.is_default ? <span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Default</span> : null}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
            <div className="flex items-center gap-3">
              <ArrowUpRight size={18} className="text-slate-500" />
              <h2 className="text-lg font-bold text-slate-950">Recent payout history</h2>
            </div>
            <div className="mt-5 space-y-3">
              {transactions.length === 0 ? (
                <SellerEmptyState message="No payout requests or finance transactions found yet." />
              ) : (
                transactions.slice(0, 10).map((transaction) => (
                  <div key={transaction.id} className="rounded-2xl border border-slate-200 px-4 py-4">
                    <div className="flex items-center justify-between gap-4">
                      <div>
                        <p className="font-semibold text-slate-900">{formatPrice(Number(transaction.amount || 0))}</p>
                        <p className="mt-1 text-xs text-slate-500">{transaction.created_at ? new Date(transaction.created_at).toLocaleString() : 'No timestamp'}</p>
                      </div>
                      <span className={`rounded-full px-3 py-1 text-xs font-bold ${String(transaction.status || '').toLowerCase() === 'completed' ? 'bg-emerald-50 text-emerald-700' : String(transaction.status || '').toLowerCase() === 'pending' ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-700'}`}>
                        {transaction.status}
                      </span>
                    </div>
                    {transaction.notes ? <p className="mt-2 text-xs text-slate-500">{transaction.notes}</p> : null}
                  </div>
                ))
              )}
            </div>
          </div>
        </section>
      </div>
    </div>
  );
};

export default SellerPayoutsPage;

import React, { useEffect, useMemo, useState } from 'react';
import {
  Plus,
  Search,
  Edit,
  Trash2,
  ExternalLink,
  AlertCircle,
  Printer,
  Archive,
} from 'lucide-react';
import { Product } from '../../../types';
import { formatPrice } from '../../../lib/utils';
import OptimizedImage from '@/features/shared/ui/OptimizedImage';
import { Link, useNavigate } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { TableSkeleton } from '@/features/shared/ui/DataSkeletons';
import { printSkuLabel, printSkuLabelSheet } from '../../../lib/skuLabel';
import toast from '@/lib/toast';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';

type ProductTab = 'all' | 'active' | 'low_stock' | 'out_of_stock';

const getInventoryStatus = (stock: number): ProductTab => {
  if (stock <= 0) return 'out_of_stock';
  if (stock < 10) return 'low_stock';
  return 'active';
};

const renderInventoryLabel = (status: ProductTab) => {
  if (status === 'out_of_stock') return 'Out of stock';
  if (status === 'low_stock') return 'Low stock';
  return 'Active';
};

const renderInventoryTone = (status: ProductTab) => {
  if (status === 'out_of_stock') return 'bg-rose-100 text-rose-700';
  if (status === 'low_stock') return 'bg-amber-100 text-amber-700';
  return 'bg-green-100 text-green-800';
};

export const SellerProductsPage = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [focusedProductId, setFocusedProductId] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
  const [activeTab, setActiveTab] = useState<ProductTab | 'all'>('all');
  const { token, user } = useUser();
  const navigate = useNavigate();

  const fetchProducts = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await fetch('/api/seller/products', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) throw new Error(data?.error || 'Failed to fetch products');
      setProducts(Array.isArray(data) ? data : []);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) void fetchProducts();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    const nextProductId = params.get('product');

    if (nextSearch) {
      setSearch(nextSearch);
    }
    if (nextProductId) {
      setFocusedProductId(nextProductId);
    }
  }, []);

  const handleDelete = async (id: number) => {
    try {
      setError('');
      const response = await fetch(`/api/products/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) throw new Error(data?.error || 'Failed to delete product');
      setDeleteConfirmId(null);
      setProducts((current) => current.filter((p) => p.id !== id));
      toast.success('Product deleted');
    } catch (err: any) {
      setError(err.message);
      toast.error(err instanceof Error ? err.message : 'Failed to delete product');
    }
  };

  const productMetrics = useMemo(() => {
    const active = products.filter((product) => getInventoryStatus(Number(product.stock || 0)) === 'active').length;
    const lowStock = products.filter((product) => getInventoryStatus(Number(product.stock || 0)) === 'low_stock').length;
    const outOfStock = products.filter((product) => getInventoryStatus(Number(product.stock || 0)) === 'out_of_stock').length;

    return {
      total: products.length,
      active,
      lowStock,
      outOfStock,
      drafts: products.filter((product) => product.product_status !== 'published').length,
    };
  }, [products]);

  const filteredProducts = useMemo(
    () =>
      products.filter((product) => {
        const inventoryStatus = getInventoryStatus(Number(product.stock || 0));
        const matchesTab = activeTab === 'all' ? true : inventoryStatus === activeTab;

        if (!matchesTab) return false;

        return (
          product.name.toLowerCase().includes(search.toLowerCase()) ||
          String(product.category || '').toLowerCase().includes(search.toLowerCase()) ||
          String(product.id).toLowerCase().includes(search.toLowerCase()) ||
          String(product.sku || '').toLowerCase().includes(search.toLowerCase())
        );
      }),
    [activeTab, products, search],
  );

  useEffect(() => {
    if (!focusedProductId) return;

    const matched = filteredProducts.find((product) => String(product.id) === focusedProductId);
    if (!matched) return;

    const timeoutId = window.setTimeout(() => {
      document.getElementById(`seller-product-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }, 120);

    return () => window.clearTimeout(timeoutId);
  }, [filteredProducts, focusedProductId]);

  const handlePrintSkuLabel = (product: Product) => {
    try {
      printSkuLabel(product);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Unable to print SKU label.');
    }
  };

  const handlePrintSkuLabelSheet = () => {
    try {
      printSkuLabelSheet(filteredProducts);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Unable to print SKU labels.');
    }
  };

  const productTabs = [
    { id: 'all', label: 'All products', count: productMetrics.total },
    { id: 'active', label: 'Active', count: productMetrics.active },
    { id: 'low_stock', label: 'Low stock', count: productMetrics.lowStock },
    { id: 'out_of_stock', label: 'Out of stock', count: productMetrics.outOfStock },
  ] as const;

  return (
    <div className="space-y-6">
      {error && (
        <div className="flex items-center space-x-2 rounded-xl bg-accent/10 p-4 text-accent">
          <AlertCircle size={20} />
          <p className="text-sm font-bold">{error}</p>
        </div>
      )}

      {user?.seller_status !== 'approved' ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          Your account is still {String(user?.seller_status || 'draft').replaceAll('_', ' ')}. Products stay private as drafts until admin approval.
        </div>
      ) : null}

      <SellerPageHeader
        eyebrow="Inventory workspace"
        title="Seller Products"
        description="Manage your inventory, pricing, and product listings with SKU-ready actions and clearer stock visibility."
        actions={
          <>
            <Link
              to="/seller/products/bulk"
              className="inline-flex h-11 items-center space-x-2 rounded-xl border border-gray-200 px-4 text-sm font-medium transition-all hover:bg-gray-50"
            >
              <Archive size={16} />
              <span>Bulk Upload</span>
            </Link>
            <button
              onClick={handlePrintSkuLabelSheet}
              className="inline-flex h-11 items-center space-x-2 rounded-xl border border-gray-200 px-4 text-sm font-medium transition-all hover:bg-gray-50"
            >
              <Printer size={16} />
              <span>Print Labels</span>
            </button>
            <Link to="/seller/products/add" className="btn-primary inline-flex h-11 items-center space-x-2">
              <Plus size={18} />
              <span>Add Product</span>
            </Link>
          </>
        }
      />

      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <SellerStatCard label="All products" value={productMetrics.total} />
        <SellerStatCard label="Active" value={productMetrics.active} tone="success" />
        <SellerStatCard label="Low stock" value={productMetrics.lowStock} tone="warning" />
        <SellerStatCard label="Out of stock" value={productMetrics.outOfStock} tone="critical" />
        <SellerStatCard label="Draft only" value={productMetrics.drafts} tone="warning" />
      </div>

      <div className="sticky top-[5.5rem] z-10 space-y-4 rounded-[1.75rem] border border-black/5 bg-white/95 p-4 shadow-sm backdrop-blur md:p-5">
        <div className="dashboard-chip-scroll -mx-1 flex gap-2 overflow-x-auto px-1">
          {productTabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              className={`inline-flex shrink-0 items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition ${
                activeTab === tab.id
                  ? 'bg-slate-950 text-white shadow-sm'
                  : 'border border-slate-200 bg-white text-slate-600 hover:border-primary/20 hover:text-primary'
              }`}
            >
              <span>{tab.label}</span>
              <span
                className={`inline-flex min-w-[1.5rem] items-center justify-center rounded-full px-2 py-0.5 text-[11px] font-bold ${
                  activeTab === tab.id ? 'bg-white/15 text-white' : 'bg-slate-100 text-slate-500'
                }`}
              >
                {tab.count}
              </span>
            </button>
          ))}
        </div>

        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div className="relative flex-1 lg:max-w-xl">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Search by name, category, id, or SKU"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="h-11 w-full rounded-xl border border-gray-200 bg-white pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary"
            />
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Link
              to="/seller/inventory"
              className="inline-flex h-11 items-center rounded-xl border border-slate-200 bg-white px-4 text-xs font-semibold text-slate-600 transition hover:border-primary/20 hover:text-primary"
            >
              Stock Control
            </Link>
            <div className="rounded-xl bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
              {filteredProducts.length} of {products.length} products visible
            </div>
          </div>
        </div>
      </div>

      <div className="overflow-hidden rounded-[1.75rem] border border-black/5 bg-white shadow-sm">
        {loading ? (
          <div className="p-4">
            <TableSkeleton rows={5} columns={6} />
          </div>
        ) : (
          <>
            <div className="space-y-3 p-4 md:hidden">
              {filteredProducts.length === 0 ? (
                <SellerEmptyState
                  message="No products found for this filter. Try a different search or add your first product."
                  action={
                    <Link to="/seller/products/add" className="inline-flex rounded-xl bg-slate-950 px-4 py-2 text-xs font-semibold text-white">
                      Add product
                    </Link>
                  }
                />
              ) : (
                filteredProducts.map((product) => {
                  const inventoryStatus = getInventoryStatus(Number(product.stock || 0));
                  return (
                    <div
                      id={`seller-product-${product.id}`}
                      key={product.id}
                      className={`rounded-2xl border p-4 shadow-sm ${
                        String(product.id) === focusedProductId
                          ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30'
                          : 'border-slate-200 bg-white'
                      }`}
                    >
                      <div className="flex items-start gap-3">
                        <OptimizedImage
                          src={product.image}
                          alt={product.name}
                          widthHint={112}
                          heightHint={112}
                          className="h-14 w-14 rounded-xl object-cover bg-gray-100"
                        />
                        <div className="min-w-0 flex-1">
                          <p className="font-bold text-gray-900">{product.name}</p>
                          <p className="mt-1 text-xs text-gray-500">SKU: {product.sku || 'Auto-generated on save'}</p>
                          <p className="mt-1 text-xs text-gray-500">{product.category}</p>
                          {Array.isArray(product.variant_options) && product.variant_options.length > 0 ? (
                            <p className="mt-1 text-xs font-medium text-slate-500">
                              {product.variant_options.length} variant group{product.variant_options.length === 1 ? '' : 's'}
                            </p>
                          ) : null}
                        </div>
                      </div>
                      <div className="mt-3 grid grid-cols-1 gap-3 rounded-2xl bg-slate-50 p-3 text-sm sm:grid-cols-3">
                        <div>
                          <p className="text-xs text-gray-500">Price</p>
                          <p className="font-bold text-primary">{formatPrice(product.price)}</p>
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">Stock</p>
                          <p className={`font-bold ${product.stock < 10 ? 'text-accent' : 'text-gray-900'}`}>{product.stock}</p>
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">Status</p>
                          <span
                            className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-bold ${renderInventoryTone(
                              inventoryStatus,
                            )}`}
                          >
                            {renderInventoryLabel(inventoryStatus)}
                          </span>
                        </div>
                      </div>
                      {deleteConfirmId === product.id ? (
                        <div className="mt-3 flex flex-wrap items-center gap-2">
                          <span className="text-xs font-medium text-rose-700">Delete this product?</span>
                          <button
                            onClick={() => handleDelete(product.id)}
                            className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-rose-700"
                          >
                            Confirm
                          </button>
                          <button
                            onClick={() => setDeleteConfirmId(null)}
                            className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition hover:bg-slate-50"
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
                          <Link
                            to={`/product/${product.slug}`}
                            target="_blank"
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-primary"
                          >
                            <ExternalLink size={16} />
                          </Link>
                          <button
                            onClick={() => handlePrintSkuLabel(product)}
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-emerald-600"
                            title="Print SKU label"
                          >
                            <Printer size={16} />
                          </button>
                          <button
                            onClick={() => navigate(`/seller/products/edit/${product.id}`)}
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-blue-500"
                            title="Edit product"
                          >
                            <Edit size={16} />
                          </button>
                          <button
                            onClick={() => setDeleteConfirmId(product.id)}
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-accent"
                            title="Delete product"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      )}
                    </div>
                  );
                })
              )}
            </div>

            <div className="hidden overflow-x-auto md:block">
              <table className="w-full border-collapse text-left">
                <thead>
                  <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
                    <th className="px-6 py-4">Product</th>
                    <th className="px-6 py-4">Category</th>
                    <th className="px-6 py-4">Price</th>
                    <th className="px-6 py-4">Stock</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredProducts.length === 0 ? (
                    <tr>
                      <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                        <div className="flex justify-center">
                          <div className="w-full max-w-md">
                            <SellerEmptyState
                              message="No products found for this filter. Try a different search or add your first product."
                              action={
                                <Link to="/seller/products/add" className="inline-flex rounded-xl bg-slate-950 px-4 py-2 text-xs font-semibold text-white">
                                  Add product
                                </Link>
                              }
                            />
                          </div>
                        </div>
                      </td>
                    </tr>
                  ) : (
                    filteredProducts.map((product) => {
                      const inventoryStatus = getInventoryStatus(Number(product.stock || 0));
                      return (
                        <tr
                          id={`seller-product-${product.id}`}
                          key={product.id}
                          className={`group transition-colors ${
                            String(product.id) === focusedProductId
                              ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200'
                              : 'hover:bg-gray-50'
                          }`}
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center space-x-3">
                              <OptimizedImage
                                src={product.image}
                                alt={product.name}
                                widthHint={96}
                                heightHint={96}
                                className="h-12 w-12 rounded-lg object-cover bg-gray-100"
                              />
                              <div className="min-w-0">
                                <p className="max-w-[220px] truncate text-sm font-bold text-gray-900">{product.name}</p>
                                <p className="text-xs text-gray-500">SKU: {product.sku || 'Auto-generated on save'}</p>
                                {Array.isArray(product.variant_options) && product.variant_options.length > 0 ? (
                                  <p className="text-[11px] text-slate-500">
                                    {product.variant_options.length} variant group{product.variant_options.length === 1 ? '' : 's'}
                                  </p>
                                ) : null}
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-600">{product.category}</td>
                          <td className="px-6 py-4 text-sm font-bold text-primary">{formatPrice(product.price)}</td>
                          <td className="px-6 py-4">
                            <div className="flex flex-col">
                              <span className={`text-sm font-bold ${product.stock < 10 ? 'text-accent' : 'text-gray-900'}`}>{product.stock}</span>
                              <div className="mt-1 h-1.5 w-16 overflow-hidden rounded-full bg-gray-100">
                                <div
                                  className={`h-full rounded-full ${product.stock < 10 ? 'bg-accent' : 'bg-primary'}`}
                                  style={{ width: `${Math.min(100, (Number(product.stock || 0) / 50) * 100)}%` }}
                                />
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-bold ${renderInventoryTone(inventoryStatus)}`}>
                              {renderInventoryLabel(inventoryStatus)}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-right">
                            {deleteConfirmId === product.id ? (
                              <div className="flex items-center justify-end gap-2">
                                <span className="text-xs font-medium text-rose-700">Delete this product?</span>
                                <button
                                  onClick={() => handleDelete(product.id)}
                                  className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-rose-700"
                                >
                                  Confirm
                                </button>
                                <button
                                  onClick={() => setDeleteConfirmId(null)}
                                  className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition hover:bg-slate-50"
                                >
                                  Cancel
                                </button>
                              </div>
                            ) : (
                              <div className="flex items-center justify-end space-x-2 opacity-0 transition-opacity group-hover:opacity-100">
                                <Link to={`/product/${product.slug}`} target="_blank" className="p-2 text-gray-400 transition-colors hover:text-primary">
                                  <ExternalLink size={18} />
                                </Link>
                                <button
                                  onClick={() => handlePrintSkuLabel(product)}
                                  className="p-2 text-gray-400 transition-colors hover:text-emerald-600"
                                  title="Print SKU label"
                                >
                                  <Printer size={18} />
                                </button>
                                <button
                                  onClick={() => navigate(`/seller/products/edit/${product.id}`)}
                                  className="p-2 text-gray-400 transition-colors hover:text-blue-500"
                                  title="Edit product"
                                >
                                  <Edit size={18} />
                                </button>
                                <button
                                  onClick={() => setDeleteConfirmId(product.id)}
                                  className="p-2 text-gray-400 transition-colors hover:text-accent"
                                  title="Delete product"
                                >
                                  <Trash2 size={18} />
                                </button>
                              </div>
                            )}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}

        <div className="flex items-center justify-between border-t border-gray-100 p-4">
          <p className="text-xs text-gray-500">
            Showing {filteredProducts.length} of {products.length} products
          </p>
          <div className="flex space-x-2">
            <button disabled className="rounded-lg border border-gray-200 px-3 py-1 text-xs font-bold disabled:opacity-50">
              Previous
            </button>
            <button disabled className="rounded-lg border border-gray-200 px-3 py-1 text-xs font-bold disabled:opacity-50">
              Next
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useCallback } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls, Environment, Grid } from '@react-three/drei';
import { Suspense } from 'react';
import ModelLoader from './ModelLoader';
import { Plus, Trash2, RotateCw, Save, Download, Home } from 'lucide-react';

interface FurnitureItem {
  id: string;
  modelUrl: string;
  name: string;
  position: [number, number, number];
  rotation: [number, number, number];
  scale: [number, number, number];
}

interface RoomVisualizerProps {
  onSave?: (design: FurnitureItem[]) => void;
  onLoadPreset?: (presetName: string) => void;
  roomDimensions?: {
    width: number;
    height: number;
    depth: number;
  };
}

const PRESET_FURNITURE = {
  sofa: {
    name: 'Modern Sofa',
    modelUrl: 'https://models.readyplayer.me/63c1d13ba4a07800087fa5d6.glb',
  },
  chair: {
    name: 'Office Chair',
    modelUrl: 'https://models.readyplayer.me/63c1d13ba4a07800087fa5d6.glb',
  },
  table: {
    name: 'Coffee Table',
    modelUrl: 'https://models.readyplayer.me/63c1d13ba4a07800087fa5d6.glb',
  },
  lamp: {
    name: 'Floor Lamp',
    modelUrl: 'https://models.readyplayer.me/63c1d13ba4a07800087fa5d6.glb',
  },
  bookshelf: {
    name: 'Bookshelf',
    modelUrl: 'https://models.readyplayer.me/63c1d13ba4a07800087fa5d6.glb',
  },
};

const RoomScene: React.FC<{
  items: FurnitureItem[];
  onItemSelect: (id: string) => void;
  onItemUpdate: (id: string, updates: Partial<FurnitureItem>) => void;
  selectedItemId?: string;
}> = ({ items, onItemSelect, onItemUpdate, selectedItemId }) => {
  return (
    <>
      {/* Room Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[10, 10]} />
        <meshStandardMaterial color="#d0d0d0" />
      </mesh>

      {/* Room Walls */}
      {/* Back wall */}
      <mesh position={[0, 2.5, -5]} receiveShadow>
        <boxGeometry args={[10, 5, 0.1]} />
        <meshStandardMaterial color="#e8e8e8" />
      </mesh>

      {/* Right wall */}
      <mesh position={[5, 2.5, 0]} receiveShadow>
        <boxGeometry args={[0.1, 5, 10]} />
        <meshStandardMaterial color="#ececec" />
      </mesh>

      {/* Left wall */}
      <mesh position={[-5, 2.5, 0]} receiveShadow>
        <boxGeometry args={[0.1, 5, 10]} />
        <meshStandardMaterial color="#ececec" />
      </mesh>

      {/* Grid helper */}
      <Grid args={[10, 10]} cellSize={0.5} cellColor="#999" sectionSize={5} />

      {/* Furniture Items */}
      {items.map((item) => (
        <group
          key={item.id}
          onClick={() => onItemSelect(item.id)}
          position={item.position}
          rotation={item.rotation}
          scale={item.scale}
        >
          <Suspense fallback={null}>
            <ModelLoader
              modelUrl={item.modelUrl}
              castShadow
              receiveShadow
            />
          </Suspense>
          {/* Selection box */}
          {selectedItemId === item.id && (
            <mesh>
              <boxGeometry args={[1, 1, 1]} />
              <meshBasicMaterial
                color="#00ff00"
                wireframe
                depthTest={true}
              />
            </mesh>
          )}
        </group>
      ))}

      {/* Lighting */}
      <ambientLight intensity={0.8} />
      <directionalLight
        position={[5, 10, 5]}
        intensity={1}
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
      />
      <pointLight position={[-5, 5, 5]} intensity={0.5} />
    </>
  );
};

export const RoomVisualizer: React.FC<RoomVisualizerProps> = ({
  onSave,
  onLoadPreset,
  roomDimensions = { width: 10, height: 5, depth: 10 },
}) => {
  const [items, setItems] = useState<FurnitureItem[]>([]);
  const [selectedItemId, setSelectedItemId] = useState<string | undefined>();
  const [furnitureType, setFurnitureType] = useState<string>('sofa');
  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const canvasRef = useRef<HTMLDivElement>(null);

  const handleAddFurniture = useCallback(() => {
    const furniture = PRESET_FURNITURE[furnitureType as keyof typeof PRESET_FURNITURE];
    if (furniture) {
      const newItem: FurnitureItem = {
        id: `item-${Date.now()}`,
        modelUrl: furniture.modelUrl,
        name: furniture.name,
        position: [0, 0, 0],
        rotation: [0, 0, 0],
        scale: [1, 1, 1],
      };
      setItems((currentItems) => [...currentItems, newItem]);
      setSelectedItemId(newItem.id);
    }
  }, [furnitureType]);

  const handleDeleteItem = useCallback(() => {
    if (selectedItemId) {
      setItems((currentItems) => currentItems.filter((item) => item.id !== selectedItemId));
      setSelectedItemId(undefined);
    }
  }, [selectedItemId]);

  const handleUpdateItem = useCallback(
    (id: string, updates: Partial<FurnitureItem>) => {
      setItems((currentItems) =>
        currentItems.map((item) => (item.id === id ? { ...item, ...updates } : item)),
      );
    },
    [],
  );

  const handleSaveDesign = useCallback(() => {
    if (!items.length) {
      setStatusMessage('Add at least one item before saving this layout.');
      return;
    }
    onSave?.(items);
    setStatusMessage('Design saved successfully.');
  }, [items, onSave]);

  const handleExportDesign = useCallback(async () => {
    if (!items.length) {
      setStatusMessage('Nothing to export yet. Add some furniture first.');
      return;
    }
    const designData = JSON.stringify(items, null, 2);
    const blob = new Blob([designData], { type: 'application/json' });
    const link = document.createElement('a');
    const objectUrl = URL.createObjectURL(blob);
    link.href = objectUrl;
    link.download = 'room-design.json';
    link.click();
    URL.revokeObjectURL(objectUrl);
    setStatusMessage('Design exported as JSON.');
  }, [items]);

  const selectedItem = items.find((item) => item.id === selectedItemId);

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Left Sidebar - Controls */}
      <div className="w-80 bg-white shadow-lg p-6 overflow-y-auto">
        <div className="space-y-6">
          {statusMessage && (
            <div className="rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-800">
              {statusMessage}
            </div>
          )}
          {/* Title */}
          <div className="flex items-center gap-2">
            <Home className="w-6 h-6 text-blue-600" />
            <h1 className="text-2xl font-bold text-gray-900">Room Visualizer</h1>
          </div>

          {/* Add Furniture Section */}
          <div className="space-y-4">
            <h2 className="text-lg font-semibold text-gray-900">Add Furniture</h2>
            <select
              value={furnitureType}
              onChange={(e) => setFurnitureType(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              {Object.entries(PRESET_FURNITURE).map(([key, value]) => (
                <option key={key} value={key}>
                  {value.name}
                </option>
              ))}
            </select>
            <button
              onClick={handleAddFurniture}
              className="w-full px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center justify-center gap-2"
            >
              <Plus className="w-5 h-5" />
              Add Item
            </button>
          </div>

          {/* Items List */}
          <div className="space-y-3">
            <h2 className="text-lg font-semibold text-gray-900">
              Placed Items ({items.length})
            </h2>
            {items.length === 0 ? (
              <p className="text-gray-500 text-sm">No items added yet</p>
            ) : (
              <div className="space-y-2">
                {items.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setSelectedItemId(item.id)}
                    className={`w-full text-left px-4 py-3 rounded-lg transition ${
                      selectedItemId === item.id
                        ? 'bg-blue-100 border-2 border-blue-500'
                        : 'bg-gray-100 border-2 border-transparent hover:bg-gray-200'
                    }`}
                  >
                    <p className="font-medium text-gray-900">{item.name}</p>
                    <p className="text-xs text-gray-500">
                      Pos: ({item.position[0].toFixed(1)}, {item.position[1].toFixed(1)})
                    </p>
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Selected Item Controls */}
          {selectedItem && (
            <div className="space-y-4 border-t pt-6">
              <h3 className="font-semibold text-gray-900">Item Properties</h3>

              {/* Position */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700">Position</label>
                <div className="space-y-2">
                  {['X', 'Y', 'Z'].map((axis, idx) => (
                    <div key={axis} className="flex items-center gap-2">
                      <label className="w-8 text-sm font-medium text-gray-600">{axis}</label>
                      <input
                        type="range"
                        min="-5"
                        max="5"
                        step="0.1"
                        value={selectedItem.position[idx]}
                        onChange={(e) => {
                          const newPos = [...selectedItem.position] as [number, number, number];
                          newPos[idx] = parseFloat(e.target.value);
                          handleUpdateItem(selectedItem.id, { position: newPos });
                        }}
                        className="flex-1"
                      />
                      <span className="w-12 text-right text-sm text-gray-600">
                        {selectedItem.position[idx].toFixed(1)}
                      </span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Rotation */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700">Rotation</label>
                <div className="space-y-2">
                  {['X', 'Y', 'Z'].map((axis, idx) => (
                    <div key={axis} className="flex items-center gap-2">
                      <label className="w-8 text-sm font-medium text-gray-600">{axis}</label>
                      <input
                        type="range"
                        min="0"
                        max={Math.PI * 2}
                        step="0.01"
                        value={selectedItem.rotation[idx]}
                        onChange={(e) => {
                          const newRot = [...selectedItem.rotation] as [number, number, number];
                          newRot[idx] = parseFloat(e.target.value);
                          handleUpdateItem(selectedItem.id, { rotation: newRot });
                        }}
                        className="flex-1"
                      />
                    </div>
                  ))}
                </div>
              </div>

              {/* Scale */}
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700">Scale</label>
                <input
                  type="range"
                  min="0.5"
                  max="3"
                  step="0.1"
                  value={selectedItem.scale[0]}
                  onChange={(e) => {
                    const scale = parseFloat(e.target.value);
                    handleUpdateItem(selectedItem.id, {
                      scale: [scale, scale, scale],
                    });
                  }}
                  className="w-full"
                />
                <p className="text-sm text-gray-600">
                  Scale: {selectedItem.scale[0].toFixed(1)}x
                </p>
              </div>

              {/* Delete Button */}
              <button
                onClick={handleDeleteItem}
                className="w-full px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition flex items-center justify-center gap-2"
              >
                <Trash2 className="w-5 h-5" />
                Delete Item
              </button>
            </div>
          )}

          {/* Save/Export */}
          <div className="space-y-2 border-t pt-6">
            <button
              onClick={handleSaveDesign}
              className="w-full px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition flex items-center justify-center gap-2"
            >
              <Save className="w-5 h-5" />
              Save Design
            </button>
            <button
              onClick={handleExportDesign}
              className="w-full px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition flex items-center justify-center gap-2"
            >
              <Download className="w-5 h-5" />
              Export as JSON
            </button>
          </div>

          {/* Room Info */}
          <div className="bg-blue-50 rounded-lg p-4 text-sm text-gray-700 space-y-1">
            <p className="font-semibold">Room Dimensions:</p>
            <p>Width: {roomDimensions.width}m</p>
            <p>Height: {roomDimensions.height}m</p>
            <p>Depth: {roomDimensions.depth}m</p>
          </div>
        </div>
      </div>

      {/* 3D Canvas */}
      <div ref={canvasRef} className="flex-1 relative">
        <Suspense
          fallback={
            <div className="w-full h-full flex items-center justify-center bg-gray-200">
              <div className="text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
                <p className="text-gray-600">Loading Room...</p>
              </div>
            </div>
          }
        >
          <Canvas
            camera={{
              position: [5, 5, 5],
              fov: 50,
            }}
            gl={{
              antialias: true,
              alpha: true,
            }}
            shadows
          >
            <RoomScene
              items={items}
              selectedItemId={selectedItemId}
              onItemSelect={setSelectedItemId}
              onItemUpdate={handleUpdateItem}
            />

            <Environment preset="apartment" />
            <OrbitControls
              enableZoom={true}
              enablePan={true}
              enableRotate={true}
              minDistance={2}
              maxDistance={20}
            />
          </Canvas>
        </Suspense>

        {/* Info Overlay */}
        <div className="absolute top-4 right-4 bg-white/90 backdrop-blur-md p-4 rounded-lg shadow-md max-w-xs">
          <h3 className="font-semibold text-gray-900 mb-2 flex items-center gap-2">
            <RotateCw className="w-4 h-4" />
            Controls
          </h3>
          <ul className="text-sm text-gray-700 space-y-1">
            <li>• Click to select items</li>
            <li>• Drag to rotate view</li>
            <li>• Scroll to zoom</li>
            <li>• Use sliders to adjust</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

