        <head>
          <meta charset="utf-8" />
          <title>Invoice ${escapeHtml(order.id)}</title>
          <style>
            @page {
              size: A4;
              margin: 14mm;
            }
            * { box-sizing: border-box; }
            body {
              font-family: Arial, sans-serif;
              background: #f8fafc;
              margin: 0;
              padding: 24px;
              color: #0f172a;
            }
            .invoice-shell {
              width: 100%;
              max-width: 794px;
              margin: 0 auto;
