              background: linear-gradient(135deg, #ffffff 0%, #ecfeff 100%);
              padding: 8px;
            }
            .brand-copy {
              display: flex;
              flex-direction: column;
              gap: 4px;
            }
            .brand-name {
              font-size: 24px;
              font-weight: 800;
              color: #0f172a;
              letter-spacing: -0.02em;
            }
            .brand-subtitle {
              font-size: 12px;
              font-weight: 700;
